window.PDLF_T = {"en":{"t002b752f7c":"Three beds, private bathroom, ideal for groups of friends or families with one child. Direct access to the garden and the beach.","t00d3f340d3":"Perched high above Lake Garda, Tignale is a renowned destination for visitors from all over the world.","t00dda435d9":"Book now →","t0157951bb7":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Mountain view</span>","t0268fb0ea8":"Didn't find your answer?","t02b83bc7a6":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Garden view</span>","t04268fbc76":"Climbing","t044ccabb57":"<span class=\"svc-ico\">🚿</span><span class=\"svc-label\">Shower</span>","t049011f98d":"The apartments are named after a citrus from the lemon house. The calamondin is a small mandarin, very juicy and sweet.","t0794554adf":"Large windows, lake light, open garden","t085726e29d":"Tignale · Via Gardesana, 7 · Porto di Tignale · Lake Garda","t092ab3f505":"Once you are here you get on perfectly well without a car: beach, lemon house and trails all start at the door. To tour the other lakeside villages, though, a car or the ferry helps.","t09ef86ca9b":"Included services","t0a015b54e8":"Check-out","t0a1b390212":"Photo gallery","t0aae14be2b":"Coming from the north: Rovereto station, bus to Riva del Garda and from there the line towards Gargnano.","t0ce18bb3ab":"Visit ecomuseopradelafam.com →","t0ec5e15397":"<span class=\"svc-ico\">🥐</span><span class=\"svc-label\">Breakfast included</span>","t0f15cc4caa":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Kitchenette</span>","t0f44bbc76e":"<span class=\"bcs-val\">29 m²</span><span class=\"bcs-lbl\">Size</span>","t0f9627b57b":"<span class=\"rv-name\">🇮🇹 Tommaso</span><span class=\"rv-date\">August 2024 · Double Room</span>","t0ffeeaad93":"from the front desk.","t116994d1f1":"Yes. The convenient stations are Brescia and Desenzano–Sirmione, on the Milan–Venice line; from there buses run along the Gardesana, more frequent from Brescia and sparser from Desenzano. Get off at the «Porto di Tignale» stop, which is right in front of us.","t119436bb10":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Outdoor space</span>","t12e5204303":"Is breakfast included?","t134b097f44":"A hotel room or an apartment — which is better?","t1475215d61":"What you see from here, and what that lemon house really is.","t163ba9bcc4":"Airy, comfortable double rooms on the first or second floor of the hotel. Some look out exclusively over Lake Garda, others combine a beautiful view of the lake with the surrounding mountains, depending on their position in the building. The furnishing is modern and welcoming. Included: air conditioning, free Wi-Fi, TV, empty fridge and free reserved parking. Bathrooms have a shower, hairdryer, towel set, shower gel and toiletries.","t1672e78ca1":"Check availability →","t16ef7fdba4":"Wood, stone and silence in the historic lemon house","t16f921ca52":"Where we are","t177195854b":"View from Malcesine to Sirmione, private garden","t189b807e55":"The economy double rooms, on the first and second floor of the hotel, are slightly more compact but just as comfortable. All of them look out over Lake Garda and are furnished in a modern, welcoming style. They have air conditioning, TV, free Wi-Fi and a empty fridge. The recently renovated bathroom has a shower, hairdryer, towel set, shower gel and toiletries. Free reserved parking included.","t1a4e01727f":"Cold-pressed. Also available citrus-infused","t1acc2b334c":"We have no swimming pool, and we have never missed it: here you swim in the lake.","t1afd65f4cd":"Contact","t1d07da6684":"Clementina Apt.","t1e5e550e0d":"Lake Garda has many historic lemon houses, but nearly all of them are empty structures: the pillars and walls remain, the trees do not. Ours is still cultivated, and it is the largest and the northernmost in Europe — it grows exactly at the climatic limit beyond which a lemon tree can no longer live outdoors.","t1e65935b2b":"Italian, English, German, French and Spanish, both at the desk and across the whole website. The family runs the place in person: whoever answers the phone is the person who will welcome you on arrival.","t1f0dbd96ab":"Rooms","t1f3d2afb49":"Double room with private bathroom, lake or garden view. Careful furnishings, new windows with no noise. Breakfast included, served on the veranda.","t207ef0e5ad":"What should I type into my satnav?","t21a221f032":"<span class=\"svc-ico\">✨</span><span class=\"svc-label\">Final cleaning</span>","t21de8404dc":"Sailing","t21e4cfe334":"Room · Prà de la Fam","t226b000df2":"Explore the property: hotel, apartments, lemon house, trails and parking. Hover over the points to see the details.","t23d419716f":"Booking directly means talking to us and not to an intermediary: special requests — the dog, breakfast in the apartment, a late arrival, a room near the garden — are settled in two lines of email.","t251c5c5589":"Accommodation","t25fcc2c679":"Can I get here without a car, by train or by plane?","t2768309b26":"What languages do you speak?","t277537d39c":"Organic extra virgin olive oil","t2779f6af30":"For anyone staying here the practical difference is simple: the lemon house is not an excursion to plan, it is the garden next to your room. And the five apartments are built inside the old lemon house itself — which is why each one is named after a citrus fruit: Clementina, Calamondino, Kumquat, Pomelo, Bergamotto.","t27c22ff3e6":"Cookies &amp;amp; Privacy","t282d4f9757":"Double Room","t29439a78d2":"Ready to<br><em>book?</em>","t294fe37686":"Hotel — 10 Rooms","t2a3ace25d3":"01 — Getting here","t2adafad680":"We are here for any question.","t2b2d8e27c6":"Organic extra virgin olive oil, clothing and accessories with the Prà de la Fam logo. Available at the hotel during your stay.","t2c4531f1c4":"Garda extra virgin olive oil","t2cdeef2a77":"<span class=\"bcs-val\">23 m²</span><span class=\"bcs-lbl\">Size</span>","t303332408e":"<span class=\"svc-ico\">🚪</span><span class=\"svc-label\">Private bathroom</span>","t303af58209":"From the west","t30de35ddfd":"Prà de la Fam · Information","t310e4bca25":"The triple rooms, on the first and second floor of the hotel, have recently been renovated and offer a beautiful view of Lake Garda. Furnished in a modern style, they include every comfort at no extra cost: TV, air conditioning, empty fridge and Wi-Fi. The bathrooms are completely new, spacious, with shower, hairdryer and toiletries.","t3182984c6c":"Check-in is from 2:00 pm to 8:00 pm, check-out by 10:30 am.","t321480eea5":"⚠️ The apartment is inside the historic lemon house and is reached by a number of steps: it is not suitable for guests with reduced mobility.","t33651bcbf3":"How is your lemon house different from the others on Lake Garda?","t33c92d054c":"The «Book» button on the site opens our booking engine, with real-time availability and instant confirmation. You can also call (+39) 0365 799890 or write to info@alpradelafam.com.","t342c9c14f0":"The forgotten trails","t34dc9f10fe":"Reviews<br><em>from our guests</em>","t34e09946bd":"<span class=\"rv-name\">🇵🇱 Tomek</span><span class=\"rv-date\">June 2025 · Economy Double Room · 7 nights</span>","t35323ab850":"It is true, and it is also why the journey is worth it. The Gardesana Occidentale is carved into the rock above the lake: narrow, with many tunnels, some of which open straight onto the water. It is one of the most scenic roads in Italy.","t35e33176d7":"Yes, the car park is private, free and reserved for guests, right in front of the building. It is enclosed, so it also works well for motorbikes — one of the things motorcyclists mention most often in their reviews.","t36cd9798d3":"Fully equipped kitchen, wooden furnishings. Lake and garden view.","t36f6028b9b":"<span class=\"bcs-val\">65 m²</span><span class=\"bcs-lbl\">Size</span>","t373f10061d":"The apartments are named after a citrus from the lemon house. The bergamot gives the essential oil at the heart of eau de cologne.","t37593677ae":"Where exactly is Prà de la Fam?","t376351c53f":"<span class=\"apt-feat\">A/C</span><span class=\"apt-feat\">Kitchen</span><span class=\"apt-feat\">WiFi</span><span class=\"apt-feat\">Double bed</span>","t37c41cd8c9":"Space and comfort for three, facing the lake","t37c595f16c":"Essential only","t380557569e":"Brenner motorway A22, Rovereto Sud exit, towards Riva del Garda, then the Gardesana towards Brescia for about twenty kilometres.","t38b0016ada":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Private bathroom</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Breakfast</span>","t398dc61e6a":"Phone","t3ba43a112b":"Area & Sport","t3bb12c5cc5":"From the west: A4 motorway, Brescia Est exit, towards Salò, about 20 km, and then as above.","t3c7ffbd79b":"Take the lake<br><em>home with you.</em>","t3ca4a501a2":"T-shirts & Sweatshirts","t3e3e2e7ec7":"📞 Call: +39 0365 799890","t3e669ed4d0":"Yes. Cold-pressed organic extra virgin olive oil, citrus-infused oil, lemons preserved in salt with chilli or pepper, limoncino with no colourings or preservatives, lemon syrup and organic lemon and bitter orange marmalades, along with clothing and accessories bearing the Prà logo.","t3e730c4314":"On the same property stands the Limonaia del Prà de la Fam: the largest and northernmost in Europe, eighty trees still in production, open to visitors from Easter to October. It is the one thing no other hotel on Lake Garda has — and the five apartments are built right there, inside the old lemon house.","t3f0a50c945":"We only ask you to tell us when you book, so we can give you the most convenient accommodation. All around there is the garden, the beach is free and the park trails start at the door: for a dog it is an easy place.","t3f47d99b7d":"Studio with double bed, kitchen and private garden with panoramic lake view.","t3f59fc3c84":"Studio with fully equipped kitchen, wooden furnishings and a large private garden.","t405e497d1d":"220 verified reviews · Booking.com","t4067735dc5":"<span class=\"room-stat-val\">4</span> <span class=\"room-stat-lbl\">Max guests</span>","t409c8e4975":"Address","t41bc46e952":"It is the largest and northernmost lemon house in Europe, and it stands inside our property: from your room you reach it on foot in a minute. It is not a ruin and it is not a reconstruction — the eighty mature trees are alive and productive.","t41c8f32a08":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Empty fridge available</span>","t4353996ec1":"<span class=\"svc-ico\">☀️</span><span class=\"svc-label\">Terrace</span>","t43a4b78b40":"Discover the apartments","t43d51909d4":"Real-time availability through our booking engine. Instant confirmation.","t44013397ef":"Yes. The beach is less than twenty metres from the garden: you cross the lawn and you are in the water. It is a small free beach, not a lido: no rows of parasols, no gates.","t44e1690ba5":"What is in the room?","t4822dcbf95":"<span class=\"room-stat-val\">16m²</span> <span class=\"room-stat-lbl\">Size</span>","t486b047c5e":"We use analytics cookies to understand how the site is used and to improve it. No data is shared with third parties for advertising.","t48a4ee031f":"It is perfectly drivable by car, motorbike and camper van — the scheduled coaches come through every day — as long as you take it slowly and do not rush when passing inside a tunnel. What we tell everyone is to allow an extra half hour and to stop in one of the lay-bys: from up there you can see the whole lake.","t49218f6b75":"There is no need to book it or mention it in advance: there is room for every guest.","t49448908e0":"<span class=\"room-stat-val\">🌊</span> <span class=\"room-stat-lbl\">Lake view</span>","t4a7cce2b7a":"A hotel with<br><em>the perfect location.</em>","t4da9c9af96":"Room","t507171eb65":"Recently renovated, with lake view and every comfort for three.","t51b9fc85e9":"Frequently asked questions","t52ec2ad3f5":"By car, by train, by plane","t52fef421c2":"Open in Google Maps →","t548a496993":"What is there to do nearby?","t558bacaaaa":"Apartment · Prà de la Fam","t5624b2aeef":"Our<br><em>apartments</em>","t5688e3684d":"The lake here is clean and deep; the swimming season runs roughly from June to September. In the morning the water is a mirror, in the afternoon the wind picks up — which is why the stretch in front of us is popular with windsurfers and kitesurfers.","t59f7f88684":"<span class=\"svc-ico\">🛎️</span><span class=\"svc-label\">Linen included</span>","t5acc558e2c":"<span class=\"svc-ico\">🚭</span><span class=\"svc-label\">Non-smoking</span>","t5be0bd6124":"All connected by train or bus to the stations of Brescia, Desenzano and Verona, from where you continue along the Gardesana.","t5c40bb1a86":"06 — What guests say","t5e16e39fef":"Canyon Adventures — canyoning specialists on Lake Garda for over 20 years. Garda canyons and Valle di Ledro.","t5f01edbe54":"<span class=\"room-stat-val\">29m²</span> <span class=\"room-stat-lbl\">Size</span>","t5ff2e24a05":"Our <em style=\"font-style:italic;color:var(--gold-titolo)\">rooms</em>","t606dccfdd7":"From the east: A4 motorway, Desenzano exit, towards Salò, about 15 km. From Salò carry on towards Riva del Garda along the Gardesana, the SS 45 bis; after Gargnano, another 4 km to Porto di Tignale.","t610f5e52ac":"Prà de la Fam, Lake Garda","t616fa8aab9":"<span class=\"bcs-val\">35 m²</span><span class=\"bcs-lbl\">Size</span>","t6649158d5f":"Ground floor + attic · Entrance from the Oldesio path","t67275fe941":"From the north","t686954d940":"The last stretch before us is a tunnel: the entrance to Prà de la Fam comes right after it, on the right if you are coming from Gargnano.","t6887a8d847":"Once the home of the lemon houses' gardener, Pomelo is today a refined apartment of about 35 m² that brings together historic charm and modern comfort. It has a private entrance, a living area with equipped kitchenette, a bright double bedroom overlooking Lake Garda and a modern bathroom. A few steps from the beach, Pomelo offers an intimate, peaceful stay, ideal for those looking for nature, silence and romance in an authentic, evocative setting.","t69ca9b15cf":"What people ask at the desk before booking.","t6a5f93783c":"<span class=\"rv-name\">🇮🇹 Antonella</span><span class=\"rv-date\">August 2024 · Family Room · 3 nights</span>","t6b0e874d96":"An artillery battery, with its trenches and protective bunkers, is spread across Monte Castello, near the sanctuary and on the northern slopes. The defensive lines, whose remains are still clearly visible, run along the Dosso Piemp — by the Rifugio degli Alpini — as far as the Passo della Puria and the edge of the municipality.","t6b6fcba8ff":"Organic jams","t6bafccbf5c":"<span class=\"apt-feat\">Lake view</span><span class=\"apt-feat\">Kitchen</span><span class=\"apt-feat\">Garden</span><span class=\"apt-feat\">A/C</span>","t6bedaf9568":"Very spacious, with several beds, designed for families with children. Large private bathroom with a big shower. Garden view and access to the beach.","t6d55b5df46":"The old lemon house of Prà now holds five studio and one-bedroom apartments, furnished with taste and elegance.","t6e341fb57d":"Exceptional.","t6e616acee6":"Triple","t6ea05b015c":"The Gardesana is narrow and full of tunnels, but it is one of the most scenic roads in Italy: take the time to look at it.","t6f4a1eab99":"The handy stations are Brescia and Desenzano–Sirmione, on the Milan–Venice line. Buses along the Gardesana are more frequent from Brescia, sparser from Desenzano. Get off at the Porto di Tignale stop.","t71f872c875":"<span class=\"svc-ico\">🧴</span><span class=\"svc-label\">Toiletries</span>","t7223c24b87":"It was restored in 1985 with the Comunità Montana of the Alto Garda Bresciano Park and is today an Ecomuseum, open to visitors from Easter to October. It has remained the property of the Parisini family, the same family that runs the hotel.","t7494b2bbce":"Calamondino Apt.","t75609dc75e":"From the north: A22 Brenner motorway, Rovereto Sud exit, towards Riva del Garda, then the Gardesana towards Brescia for about twenty kilometres. The entrance is on the Gardesana itself, with the car park in front: there is no mountain road to tackle at the last minute.","t75b631c58e":"You reach them along the old military roads still up on the heights: you can drive as far as the dirt tracks allow, then carry on on foot or by mountain bike along the old approach paths.","t75efd8f58e":"Founded in 1912, 18 holes of great tradition between Gargnano and Toscolano Maderno. The third golf club in Italy.","t7629980224":"Check availability →","t7730c4bbfd":"Visit the Bottega →","t7781fce007":"<span class=\"bcs-val\">4 guests</span><span class=\"bcs-lbl\">Capacity</span>","t778369e4af":"Circolo Vela Gargnano holds regattas every season. The traditional Centomiglia is the most awaited sailing event on Lake Garda.","t77d524feeb":"<span class=\"rv-name\">🇮🇹 Francesco</span><span class=\"rv-date\">May 2025 · Economy Double Room</span>","t785a762e36":"What time is check-in and check-out?","t7886c29db5":"<span class=\"svc-ico\">🛏️</span><span class=\"svc-label\">Double bed</span>","t79f323fa30":"Only at the hotel → Discover","t7bf6f8745f":"Beach towel & Flip-flops","t7d590f39bd":"Apartment","t7d6fd5e619":"02 — The apartments","t7dc7c098bb":"<span class=\"svc-ico\">🌊</span><span class=\"svc-label\">Lake view</span>","t7f8cf18395":"Area &<br><em>Activities</em>","t8086d463dc":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Private bathroom</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Breakfast</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">A/C</span>","t82253c0699":"If you are arriving later than 8:00 pm, call us: the place is family-run and we will work it out, we just need to know in advance. And if you arrive early, you can usually leave the car in the car park and use the garden and the beach while we finish preparing the room.","t8260aa1fca":"Breakfast is served on the veranda, in the shade of the olive trees, and the large garden is the right place to sit in the sun. The beach is less than twenty metres away.","t838f87a25f":"A rock waterfall behind, the lake and Monte Baldo in front. A working lemon house a few steps away.","t839b196b5c":"Pomelo Apt.","t84e7696a19":"Check-in","t85057929c4":"By plane","t85d43acc19":"08 — Come and see us","t86061d940c":"Right on the lake. A rock waterfall behind, the blue lake and Monte Baldo in front.","t860cb7ff5c":"The airports, from nearest to furthest: Brescia Montichiari, Verona Villafranca, Bergamo Orio al Serio, Milan Linate, Venice and Milan Malpensa, all connected by train or coach to Brescia, Desenzano and Verona.","t861e60c1c5":"Over two levels: double bedroom and bathroom on the ground floor, living area with kitchen upstairs. Exposed stone interiors with a distinctive cantilevered staircase.","t865919f6fc":"The ideal choice for enjoying Lake Garda with the best value for money. Private bathroom, essential comfort, unbeatable location.","t87da551950":"Welcome<br><em>Al Prà</em><br>de la Fam.","t888a00e0c1":"Getting here","t888f0dc89c":"Book now","t8920e8076f":"The apartments are named after a citrus from the lemon house. The pomelo is one of the three species all citrus fruits descend from: unlike the others it is not spherical, and often has the shape of a pear.","t8943b36bd7":"Is there parking? Is it paid?","t89992fa817":"Can I buy your products?","t89d8242e92":"On the first or second floor of the hotel, the family room is made up of a double room connecting to a room with bunk beds, ideal for families with children. The spaces have recently been renovated with modern, welcoming furnishings. The double room enjoys a striking lake view, while the second room faces the mountainside, ensuring quiet and privacy. The bathroom is spacious, with a large shower, hairdryer and toiletries. The room has every comfort: air conditioning, flat-screen TV, empty fridge, free Wi-Fi and a welcome kit. Access to the hotel's private parking is included.","t8a9cf1c412":"Economy Double Room","t8bc3f4c3b5":"Family Room","t8c79b16206":"All the windows have been replaced: no noise from the Gardesana road that passes in front reaches the rooms — it is one of the things guests mention most often. The property is non-smoking.","t8e20ae8c0a":"<span class=\"apt-feat\">Lake view</span><span class=\"apt-feat\">Private entrance</span><span class=\"apt-feat\">Kitchenette</span><span class=\"apt-feat\">A/C</span>","t908bad1849":"Book →","t90eab9b683":"There is one thing that confuses almost everyone, and it is better to know it before setting off: the village of Tignale sits high up on the mountain, a few kilometres of hairpin bends from the shore. We are down below, on the lake, on the Gardesana road. The exact coordinates are 45°43.684′N · 10°43.176′E.","t91922be9e2":"Salt-cured lemons","t919de81cb1":"Then canyoning in the gorges of Garda and Valle di Ledro, climbing on the rock face behind the hotel, and Golf Bogliaco, founded in 1912, the third golf club in Italy, between Gargnano and Toscolano Maderno.","t92138ee587":"Triple Room","t93167e8876":"01 — Our story","t9324d6f296":"Prà de la Fam —<br><em>Lake Garda</em>","t9363a07ad5":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">3 beds</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Private bathroom</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Breakfast</span>","t937faf91fe":"We are at Via Gardesana 7, Porto di Tignale, 25080 Tignale (BS): the Brescia shore of Lake Garda, on the road linking Gargnano to Riva del Garda. The property is right on the lake — the beach is less than twenty metres from the garden.","t961e629f7e":"Economy Double","t965334bacd":"The apartments are named after a citrus from the lemon house. The kumquat, or Chinese mandarin, bears very sweet fruit the size of a miniature orange.","t96945f98b8":"The ideal choice for experiencing Lake Garda with the best value for money.","t96a929601b":"Hotel and Apartments on Lake Garda.<br>Via Gardesana, 7 · Porto di Tignale · 25080 Tignale (BS)","t977804b6aa":"Great base for exploring this whole side of the lake. Magnificent view with access to a small beach, clean room and very kind staff.","t98513048a0":"If you would rather play safe, enter the coordinates 45°43.684′N · 10°43.176′E directly, or open our position on Google Maps from the contacts page.","t9885da33e4":"Once the home of the lemon houses' gardener, today a refined apartment with lake view and private entrance.","t98b53b16cb":"Where we really are, and how to get here without surprises.","t9d024253d4":"<span class=\"svc-ico\">❄️</span><span class=\"svc-label\">Air conditioning</span>","t9e43876d88":"<span class=\"room-stat-val\">35m²</span> <span class=\"room-stat-lbl\">Size</span>","t9f0d7907bd":"Prà de la Fam · Room","t9f202eff03":"<span class=\"bcs-val\">18 m²</span><span class=\"bcs-lbl\">Size</span>","t9f408ceb75":"The Clementina studio has a double bed, a practical fully equipped kitchen and a large bathroom with shower. Wooden furnishings, elegant finishes and functional equipment make it particularly welcoming, even in the shoulder seasons. From the windows you see the lake and the mountains around. The large private garden is perfect for an aperitivo, lunch outdoors or relaxing in the sun on the deckchairs provided.","t9ff4c942e2":"<span class=\"room-stat-val\">2</span> <span class=\"room-stat-lbl\">Max guests</span>","ta0fa0d69d8":"On the Gargnano–Riva del Garda road. Free private parking reserved for guests.","ta13fa83e74":"Right on the water, Prà is surrounded by nature. Behind it rises a rock face with a beautiful waterfall; in front, the view opens over the blue lake and Monte Baldo. The Parisini family has run the property directly for centuries.","ta1dd17aff1":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Fully equipped kitchen</span>","ta23177374a":"How do I get here by car?","ta3eb0373a9":"A4 motorway, Desenzano exit, then towards Salò: about 15 km. From Salò continue towards Riva del Garda on the Gardesana road, the SS 45 bis; past Gargnano, another 4 km to Porto di Tignale.","ta4e82da719":"Exposed stone, cantilevered staircase and reserved garden","ta505f0bda2":"In front, the open lake and Monte Baldo on the Verona shore: on clear days the view runs from Malcesine all the way to Sirmione. Behind, a few metres away, a rock wall rises with a waterfall.","ta513f6fd85":"<span class=\"svc-ico\">🏡</span><span class=\"svc-label\">Private terrace</span>","ta5d6510b68":"Double room connecting to a bunk-bed room — ideal for families with children.","ta6c3703937":"<span class=\"svc-ico\">🐾</span><span class=\"svc-label\">Pets allowed</span>","ta86d900f98":"Family","ta8ab81a313":"<span class=\"rv-name\">🇺🇸 Hua</span><span class=\"rv-date\">July 2025 · Economy Double Room</span>","ta99d92066e":"The Bergamotto apartment is set over two levels. On the ground floor there is a double bedroom and a large bathroom with shower. Upstairs, under the roof, are the living area with kitchenette and the option of a third bed. The exposed stone interiors and the cantilevered staircase linking the two levels give the space an intimate, cool atmosphere.","ta9faca02a1":"From nearest to farthest: Brescia Montichiari, Verona Villafranca, Bergamo Orio al Serio, Milan Linate, Venice and Milan Malpensa.","taa63f05b34":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Lake view</span>","taab30c2acb":"Yes, dogs are welcome, both in the rooms and in the apartments. The supplement is €10 per night per pet in the hotel and €50 per stay per pet in the apartments — not per night: for the whole stay.","tab8585e7c5":"Accept","tabbd679e0c":"In short: a room for a short, easy stay; an apartment for a week, for families with children, or for anyone who wants to do the shopping and cook.","tabc17b94c9":"The Limonaia · Ecomuseum","tabe7c8dd16":"<span class=\"svc-ico\">📶</span><span class=\"svc-label\">Free Wi-Fi</span>","tac18715e60":"Canyoning and climbing on the rock face with the waterfall behind Prà. For the bolder ones.","tae509f55e2":"In the historic lemon house","taebe065059":"They are sold at the hotel during your stay; the full range is on display at pradelafam.shop.","tafb272106a":"Apartments","tb07c72fa37":"⚠️ Apartment temporarily unavailable","tb3672026f9":"Ground floor · Private entrance","tb3879c037a":"The steady local wind lets surfers, kitesurfers and sailors enjoy the water all day long.","tb3e178fcce":"What can you see from the property?","tb498c356db":"<span>Tignale</span><span class=\"dot\">·</span><span>Lake Garda</span><span class=\"dot\">·</span><span>Hotel & Apartments</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Lemon House Ecomuseum</span><span class=\"dot\">·</span><span>Windsurfing & Kitesurfing</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>The Parisini family</span><span class=\"dot\">·</span> <span>Tignale</span><span class=\"dot\">·</span><span>Lake Garda</span><span class=\"dot\">·</span><span>Hotel & Apartments</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Lemon House Ecomuseum</span><span class=\"dot\">·</span><span>Windsurfing & Kitesurfing</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>The Parisini family</span><span class=\"dot\">·</span>","tb4aad9f0d8":"Discover","tb6c4ca4ea6":"Large windows over the lake, fully equipped kitchen, garden with private terrace. Wooden furnishings.","tb6f6d38b2a":"The Map","tb7043e80ae":"The largest and northernmost lemon house in Europe. Open to visitors from Easter to October.","tb83f0fe0df":"Can you swim? What is the beach like?","tb920ed0f41":"The Kumquat studio has a double bed, a practical kitchenette and a large bathroom with shower. From inside and from the private garden — ideal for an aperitivo, lunch outdoors or a moment of rest on the deckchairs provided — you can enjoy a magnificent view of the lake, from Malcesine all the way to Sirmione.","tba8e493ffa":"The phone is answered by the family that runs the place. Call or write: we will tell you how it really is, even when the answer is «that week we are full».","tba9319bd60":"05 — Where we are","tba9601ab9f":"03 — Rooms, apartments and services","tbb5791de12":"Fabulous","tbbc86a325d":"The <em>Limonaia</em><br>del Prà.","tbe9b82ffd6":"No colourings or preservatives, from an old local distillery","tbeaaa45bce":"Hiking & MTB","tbf926697bb":"For those staying in a room, yes, and it is included in the rate: it is served on the veranda, in the shade of the olive trees, looking out over the lake.","tbf9a913713":"A4 motorway, Brescia Est exit, then towards Salò: about 20 km. From there as above.","tbfadec1a86":"With chilli or pepper. For salads, fish or raw meat","tc00c837bbd":"<span class=\"svc-ico\">♨️</span><span class=\"svc-label\">Microwave</span>","tc058c4cdc9":"The Calamondino studio offers a splendid lake view through its large windows. It has a double bed, a kitchenette and a bathroom with shower. Wooden furnishings, careful finishes and functional equipment make it particularly comfortable, especially in the shoulder seasons. Outside, a large private garden is perfect for an aperitivo, lunch in the open air or relaxing in the sun on the deckchairs provided.","tc16b56a0bd":"For quieter days: Gargnano a few kilometres away, Limone sul Garda and Riva del Garda to the north, and the sanctuary of Montecastello above Tignale.","tc3244756f3":"Tignale lies within the Alto Garda Bresciano park, and beyond the park trails it keeps a dense web of military paths — by now forgotten by the maps — linking trenches, shelters and tunnel emplacements, casemates. Almost always at the most panoramic spots.","tc3be219c28":"<span class=\"bcs-val\">2 guests</span><span class=\"bcs-lbl\">Capacity</span>","tc4e9ccf33d":"Search →","tc4f2d54efd":"Private bathroom with shower, hairdryer, towel set, shower gel and courtesy kit; air conditioning, free Wi-Fi, television and an empty fridge at your disposal.","tc51398d85e":"<span class=\"room-stat-val\">23m²</span> <span class=\"room-stat-lbl\">Size</span>","tc5f475fec9":"<span class=\"bcs-val\">3 guests</span><span class=\"bcs-lbl\">Capacity</span>","tc5fad9b6ee":"<span class=\"room-stat-val\">65m²</span> <span class=\"room-stat-lbl\">Size</span>","tc63a6303e9":"This is not a lemon house rebuilt for visitors: it is alive and productive, and its fruit becomes the salted lemons, the limoncino and the syrup you taste at the end of the tour.","tc6ae6580d2":"Guests","tc76eb4a334":"First and second floor","tcb93134e47":"It feels like coming home. The place is enchanting, surrounded by nature, and the lake is splendid.","tcc609e0585":"<span class=\"svc-ico\">🌳</span><span class=\"svc-label\">Private garden</span>","tcd38f168ec":"Prà de la Fam® is a trademark registered in Italy by FAM S.r.l.","tce08c37a2c":"Real experiences from those who have stayed at Prà de la Fam.","tceef27f1f7":"What is the Limonaia del Prà de la Fam, and can it be visited?","tcf268eb913":"Reviews","tcf4012d7d5":"At the hotel → Discover","td075d0c609":"Bogliaco Golf","td0bf44ac3a":"The area","td0bffd1f6d":"Mugs & Accessories","td0c5b92b23":"The apartments are named after a citrus from the lemon house. The clementine is the hybrid of an orange and a mandarin.","td0e7331b28":"Windsurfing & Kitesurfing","td122cacdeb":"The gardener's old home. Private entrance, lake view, kitchenette. A few steps from the beach.","td1523d1952":"Standard Double","td1f30cb50f":"Kumquat Apt.","td2f58fcd68":"<span class=\"bcs-val\">16 m²</span><span class=\"bcs-lbl\">Size</span>","td4b6fcbd5b":"From the east","td5068d47a5":"How do I book? Is it better to book on your website?","td62becd9e0":"Type «Prà de la Fam» or «Porto di Tignale». Do not type just «Tignale»: the satnav takes you up to the village at the top of the mountain, and from there you have to come back down.","td96b889af3":"Follow us","td97b396efc":"Essential comfort, unbeatable location","tdac219b4c6":"Walking and mountain biking start right at the door: we are inside the Alto Garda Bresciano Park, and beyond the park trails there is a dense network of military paths — trenches, shelters, tunnels and casemates — long gone from the maps, almost always at the most panoramic spots.","tdd0355ae67":"Airy double rooms overlooking Lake Garda and the surrounding mountains.","tdd63715330":"The visit is guided and tells how the lemon houses of Lake Garda worked: the stone pillars, the boards that closed the greenhouse in winter, the lemon trade towards Northern Europe. At the end there is a tasting of the products made here: lemons preserved in salt, limoncino, lemon syrup and citrus-infused oil. Times and details on the dedicated website, ecomuseopradelafam.com.","tde4616b554":"It depends on how long you stay and how much you want to cook. There are ten rooms: Double Standard (18 m²), Double Economy (16 m²), Triple (23 m²) and Family (29 m²), all with private bathroom, air conditioning, Wi-Fi and breakfast included, served on the veranda. It is the simplest choice for two or three nights.","tdedb012719":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Families</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Private bathroom</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Breakfast</span>","tdef993fa85":"<span class=\"svc-ico\">🚗</span><span class=\"svc-label\">Free parking</span>","tdf027beffb":"Lemon and bitter orange. Latteria Turnaria di Tignale","tdf45fca4d2":"<span class=\"rv-name\">🇵🇱 Grzegorz</span><span class=\"rv-date\">2025 · Poland</span>","tdf7cb322cf":"Studio with large windows onto the lemon house, fully equipped kitchen and private terrace.","te212539cb8":"Book a room →","te292d68d63":"Bergamotto Apt.","te2cfa28881":"<span class=\"room-stat-val\">18m²</span> <span class=\"room-stat-lbl\">Size</span>","te3f65a8ce9":"The Limonaia of Prà de la Fam was restored in 1985 with the support of the Comunità Montana of the Alto Garda Bresciano Park. Its 80 mature trees now form the Ecomuseum, open to visitors from Easter to October.","te570deba88":"04 — Sport & Nature","te594ea220c":"Where","te5cc02c791":"<span class=\"room-stat-val\">3</span> <span class=\"room-stat-lbl\">Max guests</span>","te5de2cbb0d":"Prà de la Fam · Apartment","te5e331d5c9":"The Limonaia","te6b441803d":"<span class=\"svc-ico\">📺</span><span class=\"svc-label\">Television</span>","te8106f1430":"Fantastic position, a little pearl set on Lake Garda. Matteo, the owner and manager, is extremely kind and told us and recommended so many things. Exclusive location, a beautiful and charming place — I would come back a thousand times. Private, gated parking (great if you ride a motorbike like me) and new windows: no noise at all in the room.","te8c99f06b1":"Hotel and Apartments right on Lake Garda, inside the northernmost historic lemon house in Europe. A rock waterfall behind, the blue lake in front — where time stands still.","teb07e74228":"02 — The setting and the lemon house","tec5181be2c":"These are the questions we really get on the phone and at the desk, answered in full — the same way we would answer in person. If what you are looking for is not here, call us: you get us, not a call centre.","tecb5de2726":"Trails start on foot right from the hotel: paths of the Alto Garda Park and scenic historic military routes.","ted709911db":"Airy, modern, lake or mountain view","tede794f1e2":"03 — Ecomuseum","tef84d416a9":"By train","tefcd26e01b":"Where<br><em>we are</em>","tf03b6bab86":"Not for the apartments, since they have a kitchen: those who want it can add it for a fee. Just tell us when you book, or even the day before at the desk.","tf08ba2a641":"Our<br><em>property</em>","tf11b96d58c":"The rooms have a lake or mountain view depending on where they are in the building; the apartments all look onto the lake. Breakfast is served on the veranda, in the shade of the olive trees, with the lake in front of you.","tf1c8b4462a":"By car","tf2137a9a21":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Fridge</span>","tf27cd0f01e":"<span class=\"svc-ico\">💨</span><span class=\"svc-label\">Hairdryer</span>","tf297f278b2":"Set in Tignale, a characteristic village on Lake Garda along the road to Riva, a few kilometres from Gargnano, Prà de la Fam enjoys an ideal position for a quiet holiday or an active one.","tf3822d6248":"What is the road like? I have read it is narrow and full of tunnels.","tf38421c0d2":"Via Gardesana, 7 · Sponda bresciana<br>Gargnano–Riva del Garda road","tf4467cd18b":"Questions","tf561d3c688":"The gardener's old home, brought back to life","tf5795ea6fe":"View from Malcesine to Sirmione, private garden with deckchairs. Kitchenette, bathroom with shower.","tf757da1422":"Nature","tf946f40316":"Rooms","tfc36cf0b38":"Windsurfing, kitesurfing and sailing: the wind on Lake Garda is steady and reliable, and the Circolo Vela Gargnano holds regattas throughout the season, including the historic Centomiglia.","tfde24d0272":"Two-room apartment over two levels, exposed stone inside, cantilevered staircase and reserved garden. The largest on the property.","tfe69b1ca69":"Two connecting rooms for the whole family","tfe6bf92cf4":"The property still belongs to the Parisini family. Guided tours tell the story and the peculiarities of the lemon house, and end with a tasting of the products: salt-cured lemons, limoncino, lemon syrup and citrus-infused olive oil.","tff0a201186":"Limoncino liqueur","tff12d938aa":"Book online","tff9b24f4c2":"The apartments are carved out of the old lemon house: Clementina, Calamondino, Kumquat and Pomelo are about 35 m² for two people, with a fully equipped kitchen or kitchenette, outdoor space and lake view; Bergamotto is on two levels, 65 m², but is currently not available.","tffdf35b0f8":"Are dogs allowed?"},"de":{"t002b752f7c":"Drei Betten, eigenes Bad, ideal für Freundesgruppen oder Familien mit einem Kind. Direkter Zugang zu Garten und Strand.","t00d3f340d3":"Hoch über dem Gardasee gelegen, ist Tignale ein bekanntes Ziel für Gäste aus aller Welt.","t00dda435d9":"Jetzt buchen →","t0157951bb7":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Bergblick</span>","t0268fb0ea8":"Ihre Frage war nicht dabei?","t02b83bc7a6":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Gartenblick</span>","t04268fbc76":"Klettern","t044ccabb57":"<span class=\"svc-ico\">🚿</span><span class=\"svc-label\">Dusche</span>","t049011f98d":"Die Apartments tragen den Namen einer Zitrusfrucht aus der Limonaia. Die Calamondin ist eine kleine Mandarine, sehr saftig und süß.","t0794554adf":"Große Fenster, Seelicht, offener Garten","t085726e29d":"Tignale · Via Gardesana, 7 · Porto di Tignale · Gardasee","t092ab3f505":"Einmal hier, kommt man auch gut ohne Auto zurecht: Strand, Limonaia und Wanderwege beginnen vor der Tür. Um die anderen Orte am See zu erkunden, helfen allerdings Auto oder Schiff.","t09ef86ca9b":"Inklusivleistungen","t0a015b54e8":"Abreise","t0a1b390212":"Fotogalerie","t0aae14be2b":"Aus dem Norden: Bahnhof Rovereto, Bus bis Riva del Garda und von dort die Linie Richtung Gargnano.","t0ce18bb3ab":"Besuchen Sie ecomuseopradelafam.com →","t0ec5e15397":"<span class=\"svc-ico\">🥐</span><span class=\"svc-label\">Frühstück inklusive</span>","t0f15cc4caa":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Kochnische</span>","t0f44bbc76e":"<span class=\"bcs-val\">29 m²</span><span class=\"bcs-lbl\">Fläche</span>","t0f9627b57b":"<span class=\"rv-name\">🇮🇹 Tommaso</span><span class=\"rv-date\">August 2024 · Doppelzimmer</span>","t0ffeeaad93":"an der Rezeption.","t116994d1f1":"Ja. Praktisch sind die Bahnhöfe Brescia und Desenzano–Sirmione an der Linie Mailand–Venedig; von dort fahren Busse entlang der Gardesana, häufiger ab Brescia, seltener ab Desenzano. Aussteigen an der Haltestelle «Porto di Tignale», die direkt vor uns liegt.","t119436bb10":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Außenbereich</span>","t12e5204303":"Ist das Frühstück inbegriffen?","t134b097f44":"Lieber ein Hotelzimmer oder ein Apartment?","t1475215d61":"Was man von hier aus sieht — und was es mit dieser Limonaia auf sich hat.","t163ba9bcc4":"Luftige, komfortable Doppelzimmer im ersten oder zweiten Stock des Hotels. Einige bieten ausschließlich Blick auf den Gardasee, andere verbinden je nach Lage im Haus den Seeblick mit den umliegenden Bergen. Die Einrichtung ist modern und einladend. Inklusive: Klimaanlage, kostenloses WLAN, TV, leerer Kühlschrank und kostenloser reservierter Parkplatz. Die Bäder verfügen über Dusche, Haartrockner, Handtuchset, Duschgel und Pflegeset.","t1672e78ca1":"Verfügbarkeit prüfen →","t16ef7fdba4":"Holz, Stein und Stille im historischen Zitronenhaus","t16f921ca52":"Wo wir sind","t177195854b":"Blick von Malcesine bis Sirmione, Privatgarten","t189b807e55":"Die Economy-Doppelzimmer im ersten und zweiten Stock sind etwas kompakter, aber ebenso komfortabel. Alle bieten Blick auf den Gardasee und sind modern und einladend eingerichtet. Mit Klimaanlage, TV, kostenlosem WLAN und leerer Kühlschrank. Das kürzlich renovierte Bad verfügt über Dusche, Haartrockner, Handtuchset, Duschgel und Pflegeset. Kostenloser reservierter Parkplatz inklusive.","t1a4e01727f":"Kaltgepresst. Auch als Zitrusöl erhältlich","t1acc2b334c":"Wir haben keinen Pool, und wir haben ihn nie vermisst: Hier schwimmt man im See.","t1afd65f4cd":"Kontakt","t1d07da6684":"Apt. Clementina","t1e5e550e0d":"Am Gardasee gibt es viele historische Limonaie, doch fast alle sind leere Bauten: Pfeiler und Mauern stehen noch, die Pflanzen nicht. Unsere wird weiterhin bewirtschaftet und ist die größte und nördlichste Europas — sie wächst genau an der Klimagrenze, jenseits derer eine Zitrone im Freien nicht mehr überlebt.","t1e65935b2b":"Italienisch, Englisch, Deutsch, Französisch und Spanisch — an der Rezeption und auf der gesamten Website. Die Familie führt das Haus persönlich: Wer ans Telefon geht, empfängt Sie auch bei der Ankunft.","t1f0dbd96ab":"Zimmer","t1f3d2afb49":"Doppelzimmer mit eigenem Bad, See- oder Gartenblick. Sorgfältige Einrichtung, neue Fenster ohne Lärm. Frühstück inklusive, auf der Veranda serviert.","t207ef0e5ad":"Was soll ich ins Navi eingeben?","t21a221f032":"<span class=\"svc-ico\">✨</span><span class=\"svc-label\">Endreinigung</span>","t21de8404dc":"Segeln","t21e4cfe334":"Zimmer · Prà de la Fam","t226b000df2":"Erkunden Sie das Anwesen: Hotel, Apartments, Limonaia, Wege und Parkplatz. Fahren Sie über die Punkte, um Details zu sehen.","t23d419716f":"Wer direkt bucht, spricht mit uns und nicht mit einem Vermittler: Besondere Wünsche — der Hund, Frühstück im Apartment, späte Anreise, ein Zimmer nahe am Garten — klären sich in zwei Zeilen per E-Mail.","t251c5c5589":"Unterkünfte","t25fcc2c679":"Kommt man auch ohne Auto her, mit Zug oder Flugzeug?","t2768309b26":"Welche Sprachen sprechen Sie?","t277537d39c":"Bio-Olivenöl extra vergine","t2779f6af30":"Für unsere Gäste ist der praktische Unterschied einfach: Die Limonaia ist kein Ausflug, den man planen muss, sondern der Garten neben dem Zimmer. Und die fünf Apartments sind genau in der alten Limonaia entstanden — deshalb trägt jedes den Namen einer Zitrusfrucht: Clementina, Calamondino, Kumquat, Pomelo, Bergamotto.","t27c22ff3e6":"Cookies &amp;amp; Datenschutz","t282d4f9757":"Doppelzimmer","t29439a78d2":"Bereit zu<br><em>buchen?</em>","t294fe37686":"Hotel — 10 Zimmer","t2a3ace25d3":"01 — Anfahrt und Straße","t2adafad680":"Für Fragen stehen wir Ihnen gern zur Verfügung.","t2b2d8e27c6":"Bio-Olivenöl extra vergine, Kleidung und Accessoires mit dem Logo des Prà de la Fam. Während des Aufenthalts im Hotel erhältlich.","t2c4531f1c4":"Garda-Olivenöl extra vergine","t2cdeef2a77":"<span class=\"bcs-val\">23 m²</span><span class=\"bcs-lbl\">Fläche</span>","t303332408e":"<span class=\"svc-ico\">🚪</span><span class=\"svc-label\">Eigenes Bad</span>","t303af58209":"Von Westen","t30de35ddfd":"Prà de la Fam · Informationen","t310e4bca25":"Die Dreibettzimmer im ersten und zweiten Stock wurden kürzlich renoviert und bieten einen herrlichen Blick auf den Gardasee. Modern eingerichtet, mit allen Annehmlichkeiten ohne Aufpreis: TV, Klimaanlage, leerer Kühlschrank und WLAN. Die Bäder sind komplett neu, geräumig, mit Dusche, Haartrockner und Pflegeset.","t3182984c6c":"Check-in von 14:00 bis 20:00 Uhr, Check-out bis 10:30 Uhr.","t321480eea5":"⚠️ Das Apartment liegt im historischen Zitronenhaus und ist nur über zahlreiche Stufen erreichbar: für Gäste mit eingeschränkter Mobilität nicht geeignet.","t33651bcbf3":"Worin unterscheidet sich Ihre Limonaia von den anderen am Gardasee?","t33c92d054c":"Über die Schaltfläche «Buchen» auf der Website öffnet sich unser Buchungssystem mit tagesaktueller Verfügbarkeit und sofortiger Bestätigung. Alternativ können Sie unter (+39) 0365 799890 anrufen oder an info@alpradelafam.com schreiben.","t342c9c14f0":"Die vergessenen Pfade","t34dc9f10fe":"Bewertungen<br><em>unserer Gäste</em>","t34e09946bd":"<span class=\"rv-name\">🇵🇱 Tomek</span><span class=\"rv-date\">Juni 2025 · Doppelzimmer Economy · 7 Nächte</span>","t35323ab850":"Das stimmt — und genau deshalb lohnt sich die Fahrt. Die Gardesana Occidentale ist in den Fels über dem See geschlagen: eng, mit vielen Tunneln, von denen sich einige direkt zum Wasser hin öffnen. Sie ist eine der schönsten Panoramastraßen Italiens.","t35e33176d7":"Ja, der Parkplatz ist privat, kostenlos und den Gästen vorbehalten, direkt vor dem Haus. Er ist geschlossen und eignet sich daher auch für Motorräder — was Motorradfahrer besonders oft in ihren Bewertungen erwähnen.","t36cd9798d3":"Voll ausgestattete Küche, Holzmöbel. See- und Gartenblick.","t36f6028b9b":"<span class=\"bcs-val\">65 m²</span><span class=\"bcs-lbl\">Fläche</span>","t373f10061d":"Die Apartments tragen den Namen einer Zitrusfrucht aus der Limonaia. Die Bergamotte liefert das ätherische Öl, das die Grundlage des Kölnisch Wassers bildet.","t37593677ae":"Wo genau liegt Prà de la Fam?","t376351c53f":"<span class=\"apt-feat\">A/C</span><span class=\"apt-feat\">Küche</span><span class=\"apt-feat\">WLAN</span><span class=\"apt-feat\">Doppelbett</span>","t37c41cd8c9":"Platz und Komfort für drei, mit Blick auf den See","t37c595f16c":"Nur notwendige","t380557569e":"Brennerautobahn A22, Ausfahrt Rovereto Süd, Richtung Riva del Garda, dann die Gardesana Richtung Brescia für rund zwanzig Kilometer.","t38b0016ada":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WLAN</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Eigenes Bad</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Frühstück</span>","t398dc61e6a":"Telefon","t3ba43a112b":"Umgebung & Sport","t3bb12c5cc5":"Von Westen: Autobahn A4, Ausfahrt Brescia Est, Richtung Salò, rund 20 km, dann wie oben.","t3c7ffbd79b":"Nimm den See<br><em>mit nach Hause.</em>","t3ca4a501a2":"T-Shirts & Sweatshirts","t3e3e2e7ec7":"📞 Anrufen: +39 0365 799890","t3e669ed4d0":"Ja. Kaltgepresstes Bio-Olivenöl extra vergine, Zitrusöl, in Salz eingelegte Zitronen mit Chili oder Pfeffer, Limoncino ohne Farb- und Konservierungsstoffe, Zitronensirup und Bio-Marmeladen aus Zitrone und Bitterorange, dazu Kleidung und Accessoires mit dem Logo des Prà.","t3e730c4314":"Auf demselben Grundstück liegt die Limonaia del Prà de la Fam: die größte und nördlichste Europas, achtzig Bäume, die noch tragen, von Ostern bis Oktober zu besichtigen. Das hat kein anderes Hotel am Gardasee — und die fünf Apartments sind genau dort entstanden, in der alten Limonaia.","t3f0a50c945":"Wir bitten Sie nur, es bei der Buchung anzugeben, damit wir Ihnen die passendste Unterkunft zuweisen können. Ringsum liegt der Garten, der Strand ist frei zugänglich und die Wege des Parks beginnen vor der Tür: für einen Hund ein einfacher Ort.","t3f47d99b7d":"Studio mit Doppelbett, Küche und Privatgarten mit Panoramablick auf den See.","t3f59fc3c84":"Studio mit voll ausgestatteter Küche, Holzmöbeln und großem Privatgarten.","t405e497d1d":"220 verifizierte Bewertungen · Booking.com","t4067735dc5":"<span class=\"room-stat-val\">4</span> <span class=\"room-stat-lbl\">Max. Gäste</span>","t409c8e4975":"Adresse","t41bc46e952":"Sie ist die größte und nördlichste Limonaia Europas und liegt auf unserem Grundstück: Vom Zimmer aus geht man eine Minute zu Fuß. Sie ist keine Ruine und keine Rekonstruktion — die achtzig ausgewachsenen Bäume leben und tragen Früchte.","t41c8f32a08":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Leerer Kühlschrank verfügbar</span>","t4353996ec1":"<span class=\"svc-ico\">☀️</span><span class=\"svc-label\">Terrasse</span>","t43a4b78b40":"Apartments entdecken","t43d51909d4":"Verfügbarkeit in Echtzeit über unser Buchungssystem. Sofortige Bestätigung.","t44013397ef":"Ja. Der Strand liegt keine zwanzig Meter vom Garten entfernt: über die Wiese, und man ist im Wasser. Es ist ein kleiner freier Strand, kein Strandbad: keine Schirmreihen, keine Schranken.","t44e1690ba5":"Was gibt es im Zimmer?","t4822dcbf95":"<span class=\"room-stat-val\">16m²</span> <span class=\"room-stat-lbl\">Fläche</span>","t486b047c5e":"Wir verwenden Analyse-Cookies, um zu verstehen, wie die Seite genutzt wird, und sie zu verbessern. Es werden keine Daten zu Werbezwecken an Dritte weitergegeben.","t48a4ee031f":"Sie lässt sich problemlos mit Auto, Motorrad und Wohnmobil befahren — die Linienbusse fahren hier täglich durch —, sofern man langsam fährt und beim Begegnen im Tunnel keine Eile hat. Unser Rat an alle: eine halbe Stunde mehr einplanen und an einer der Haltebuchten anhalten — von dort sieht man den ganzen See.","t49218f6b75":"Sie müssen ihn weder reservieren noch vorher ankündigen: Es ist Platz für alle Gäste.","t49448908e0":"<span class=\"room-stat-val\">🌊</span> <span class=\"room-stat-lbl\">Seeblick</span>","t4a7cce2b7a":"Ein Hotel mit<br><em>idealer Lage.</em>","t4da9c9af96":"Zimmer","t507171eb65":"Kürzlich renoviert, mit Seeblick und allem Komfort für drei Personen.","t51b9fc85e9":"Häufige Fragen","t52ec2ad3f5":"Mit Auto, Zug oder Flugzeug","t52fef421c2":"In Google Maps öffnen →","t548a496993":"Was kann man in der Umgebung unternehmen?","t558bacaaaa":"Apartment · Prà de la Fam","t5624b2aeef":"Unsere<br><em>Apartments</em>","t5688e3684d":"Der See ist hier sauber und tief; die Badesaison reicht etwa von Juni bis September. Morgens liegt das Wasser spiegelglatt, nachmittags kommt der Wind auf — deshalb ist der Abschnitt vor uns bei Windsurfern und Kitesurfern beliebt.","t59f7f88684":"<span class=\"svc-ico\">🛎️</span><span class=\"svc-label\">Bettwäsche inklusive</span>","t5acc558e2c":"<span class=\"svc-ico\">🚭</span><span class=\"svc-label\">Nichtraucher</span>","t5be0bd6124":"Alle mit Zug oder Bus an die Bahnhöfe Brescia, Desenzano und Verona angebunden, von wo es entlang der Gardesana weitergeht.","t5c40bb1a86":"06 — Was Gäste sagen","t5e16e39fef":"Canyon Adventures — seit über 20 Jahren Canyoning-Spezialisten am Gardasee. Garda-Schluchten und Valle di Ledro.","t5f01edbe54":"<span class=\"room-stat-val\">29m²</span> <span class=\"room-stat-lbl\">Fläche</span>","t5ff2e24a05":"Unsere <em style=\"font-style:italic;color:var(--gold-titolo)\">Zimmer</em>","t606dccfdd7":"Von Osten: Autobahn A4, Ausfahrt Desenzano, Richtung Salò, rund 15 km. Ab Salò weiter Richtung Riva del Garda auf der Gardesana, der SS 45 bis; nach Gargnano noch 4 km bis Porto di Tignale.","t610f5e52ac":"Prà de la Fam, Gardasee","t616fa8aab9":"<span class=\"bcs-val\">35 m²</span><span class=\"bcs-lbl\">Fläche</span>","t6649158d5f":"Erdgeschoss + Dachgeschoss · Eingang vom Oldesio-Weg","t67275fe941":"Von Norden","t686954d940":"Der letzte Abschnitt vor uns führt durch einen Tunnel: Die Einfahrt zum Prà de la Fam kommt gleich danach, rechts, wenn Sie aus Richtung Gargnano kommen.","t6887a8d847":"Einst Wohnhaus des Gärtners der Zitronenhäuser, ist Pomelo heute ein feines Apartment von rund 35 m², das historischen Charme und modernen Komfort verbindet. Es verfügt über einen separaten Eingang, einen Wohnbereich mit ausgestatteter Kochnische, ein helles Doppelschlafzimmer mit Blick auf den Gardasee und ein modernes Bad. Nur wenige Schritte vom Strand entfernt bietet Pomelo einen intimen, ruhigen Aufenthalt — ideal für alle, die Natur, Stille und Romantik in einer authentischen Umgebung suchen.","t69ca9b15cf":"Was man vor der Buchung an der Rezeption fragt.","t6a5f93783c":"<span class=\"rv-name\">🇮🇹 Antonella</span><span class=\"rv-date\">August 2024 · Familienzimmer · 3 Nächte</span>","t6b0e874d96":"Eine Artilleriebatterie mit Schützengräben und Schutzbunkern zieht sich über den ganzen Monte Castello, nahe der Wallfahrtskirche und an den Nordhängen. Die Verteidigungslinien, deren Reste gut sichtbar geblieben sind, verlaufen weiter über den Dosso Piemp — beim Rifugio degli Alpini — bis zum Passo della Puria und zur Gemeindegrenze.","t6b6fcba8ff":"Bio-Marmeladen","t6bafccbf5c":"<span class=\"apt-feat\">Seeblick</span><span class=\"apt-feat\">Küche</span><span class=\"apt-feat\">Garten</span><span class=\"apt-feat\">A/C</span>","t6bedaf9568":"Sehr geräumig, mit mehreren Betten, gedacht für Familien mit Kindern. Großes eigenes Bad mit geräumiger Dusche. Gartenblick und Zugang zum Strand.","t6d55b5df46":"Das alte Zitronenhaus des Prà beherbergt heute fünf Studio- und Zweizimmer-Apartments, geschmackvoll und elegant eingerichtet.","t6e341fb57d":"Außergewöhnlich.","t6e616acee6":"Dreibett","t6ea05b015c":"Die Gardesana ist schmal und voller Tunnel, aber sie ist eine der schönsten Panoramastraßen Italiens: nehmen Sie sich die Zeit, sie anzuschauen.","t6f4a1eab99":"Die günstigen Bahnhöfe sind Brescia und Desenzano–Sirmione an der Linie Mailand–Venedig. Von Brescia fahren die Busse entlang der Gardesana häufiger, von Desenzano seltener. Ausstieg an der Haltestelle Porto di Tignale.","t70f8bb9a8a":"Startseite","t71f872c875":"<span class=\"svc-ico\">🧴</span><span class=\"svc-label\">Pflegeset</span>","t7223c24b87":"1985 wurde sie mit der Comunità Montana des Parks Alto Garda Bresciano restauriert und ist heute ein Ökomuseum, von Ostern bis Oktober zu besichtigen. Sie ist im Besitz der Familie Parisini geblieben — derselben Familie, die das Hotel führt.","t7494b2bbce":"Apt. Calamondino","t75609dc75e":"Von Norden: Brennerautobahn A22, Ausfahrt Rovereto Süd, Richtung Riva del Garda, dann auf der Gardesana etwa zwanzig Kilometer Richtung Brescia. Die Einfahrt liegt direkt an der Gardesana, der Parkplatz davor: Es gibt keine Bergstraße, die man zum Schluss noch bewältigen müsste.","t75b631c58e":"Erreichbar sind sie über die alten Militärstraßen, die in der Höhe geblieben sind: mit dem Fahrzeug kommt man so weit, wie die Schotterwege befahrbar sind, danach geht es zu Fuß oder mit dem Mountainbike auf den alten Zustiegspfaden weiter.","t75efd8f58e":"1912 gegründet, 18 traditionsreiche Löcher zwischen Gargnano und Toscolano Maderno. Der drittälteste Golfclub Italiens.","t7629980224":"Verfügbarkeit prüfen →","t7730c4bbfd":"Zur Bottega →","t7781fce007":"<span class=\"bcs-val\">4 Pers.</span><span class=\"bcs-lbl\">Belegung</span>","t778369e4af":"Der Circolo Vela Gargnano veranstaltet jede Saison Regatten. Die traditionelle Centomiglia ist das meisterwartete Segelereignis am Gardasee.","t77d524feeb":"<span class=\"rv-name\">🇮🇹 Francesco</span><span class=\"rv-date\">Mai 2025 · Doppelzimmer Economy</span>","t785a762e36":"Wann sind Check-in und Check-out?","t7886c29db5":"<span class=\"svc-ico\">🛏️</span><span class=\"svc-label\">Doppelbett</span>","t79f323fa30":"Nur im Hotel → Entdecken","t7bf6f8745f":"Strandtuch & Flip-Flops","t7d590f39bd":"Apartment","t7d6fd5e619":"02 — Die Apartments","t7dc7c098bb":"<span class=\"svc-ico\">🌊</span><span class=\"svc-label\">Seeblick</span>","t7f8cf18395":"Umgebung &<br><em>Aktivitäten</em>","t8086d463dc":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WLAN</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Eigenes Bad</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Frühstück</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">A/C</span>","t82253c0699":"Wenn Sie später als 20:00 Uhr ankommen, rufen Sie an: Das Haus wird familiär geführt, wir richten uns ein — wir müssen es nur vorher wissen. Und wenn Sie früher da sind, können Sie in der Regel schon das Auto abstellen und Garten und Strand nutzen, während wir das Zimmer fertig machen.","t8260aa1fca":"Das Frühstück wird auf der Veranda im Schatten der Olivenbäume serviert, und der große Garten ist der richtige Ort zum Sonnen. Der Strand liegt keine zwanzig Meter entfernt.","t838f87a25f":"Ein Wasserfall im Fels im Rücken, der See und der Monte Baldo davor. Eine noch bewirtschaftete Limonaia gleich nebenan.","t839b196b5c":"Apt. Pomelo","t84add5b295":"E-Mail","t84e7696a19":"Anreise","t85057929c4":"Mit dem Flugzeug","t85d43acc19":"08 — Besuchen Sie uns","t86061d940c":"Direkt am See. Im Rücken ein Wasserfall im Fels, davor der blaue See und der Monte Baldo.","t860cb7ff5c":"Die Flughäfen, vom nächsten zum entferntesten: Brescia Montichiari, Verona Villafranca, Bergamo Orio al Serio, Mailand Linate, Venedig und Mailand Malpensa — alle per Zug oder Bus mit Brescia, Desenzano und Verona verbunden.","t861e60c1c5":"Auf zwei Ebenen: Doppelschlafzimmer und Bad im Erdgeschoss, Wohnbereich mit Küche im Dachgeschoss. Sichtsteinwände mit charakteristischer freitragender Treppe.","t865919f6fc":"Die ideale Wahl, um den Gardasee mit dem besten Preis-Leistungs-Verhältnis zu genießen. Eigenes Bad, das Wesentliche an Komfort, unschlagbare Lage.","t87da551950":"Willkommen<br><em>Al Prà</em><br>de la Fam.","t888a00e0c1":"Anreise","t888f0dc89c":"Jetzt buchen","t8920e8076f":"Die Apartments tragen den Namen einer Zitrusfrucht aus der Limonaia. Die Pomelo ist eine der drei Arten, von denen alle Zitrusfrüchte abstammen: anders als die übrigen ist sie nicht kugelig, sondern oft birnenförmig.","t8943b36bd7":"Gibt es Parkplätze? Kosten sie etwas?","t89992fa817":"Kann man Ihre Produkte kaufen?","t89d8242e92":"Im ersten oder zweiten Stock des Hotels besteht das Familienzimmer aus einem Doppelzimmer mit Verbindungstür zu einem Zimmer mit Etagenbett — ideal für Familien mit Kindern. Die Räume wurden kürzlich modern und einladend renoviert. Das Doppelzimmer bietet einen eindrucksvollen Seeblick, das zweite Zimmer liegt zum Berg hin und sorgt für Ruhe und Privatsphäre. Das Bad ist geräumig, mit großer Dusche, Haartrockner und Pflegelinie. Das Zimmer verfügt über allen Komfort: Klimaanlage, Flachbild-TV, leerer Kühlschrank, kostenloses WLAN und Willkommensset. Der Zugang zum hoteleigenen Parkplatz ist inbegriffen.","t8a9cf1c412":"Doppelzimmer Economy","t8bc3f4c3b5":"Familienzimmer","t8c79b16206":"Alle Fenster wurden erneuert: Von der Gardesana, die hier vorbeiführt, dringt kein Lärm ins Zimmer — das erwähnen die Gäste besonders oft. Das Haus ist Nichtraucherhaus.","t8e20ae8c0a":"<span class=\"apt-feat\">Seeblick</span><span class=\"apt-feat\">Separater Eingang</span><span class=\"apt-feat\">Kochnische</span><span class=\"apt-feat\">A/C</span>","t908bad1849":"Buchen →","t90eab9b683":"Eines verwirrt fast alle, und man sollte es vor der Abfahrt wissen: Das Dorf Tignale liegt oben am Berg, ein paar Serpentinen-Kilometer vom Ufer entfernt. Wir sind unten, direkt am See, an der Gardesana. Die genauen Koordinaten lauten 45°43.684′N · 10°43.176′E.","t91922be9e2":"Zitronen in Salz","t919de81cb1":"Dazu Canyoning in den Schluchten des Gardasees und des Ledrotals, Klettern an der Felswand hinter dem Hotel und der Golf Bogliaco, 1912 gegründet, der drittälteste Golfclub Italiens, zwischen Gargnano und Toscolano Maderno.","t92138ee587":"Dreibettzimmer","t93167e8876":"01 — Unsere Geschichte","t9324d6f296":"Prà de la Fam —<br><em>Gardasee</em>","t9363a07ad5":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WLAN</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">3 Betten</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Eigenes Bad</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Frühstück</span>","t937faf91fe":"Wir liegen in der Via Gardesana 7, Porto di Tignale, 25080 Tignale (BS): am Brescianer Ufer des Gardasees, an der Straße von Gargnano nach Riva del Garda. Das Haus liegt direkt am See — der Strand ist keine zwanzig Meter vom Garten entfernt.","t961e629f7e":"Doppelzimmer Economy","t965334bacd":"Die Apartments tragen den Namen einer Zitrusfrucht aus der Limonaia. Die Kumquat, auch chinesische Mandarine, trägt sehr süße Früchte, klein wie eine Miniaturorange.","t96945f98b8":"Die ideale Wahl, um den Gardasee mit dem besten Preis-Leistungs-Verhältnis zu erleben.","t96a929601b":"Hotel und Apartments am Gardasee.<br>Via Gardesana, 7 · Porto di Tignale · 25080 Tignale (BS)","t977804b6aa":"Hervorragende Lage, um diese ganze Seeseite zu erkunden. Großartiger Blick mit Zugang zu einem kleinen Strand, sauberes Zimmer und sehr freundliches Personal.","t98513048a0":"Wer ganz sichergehen will, gibt direkt die Koordinaten 45°43.684′N · 10°43.176′E ein oder öffnet unsere Position über die Kontaktseite in Google Maps.","t9885da33e4":"Einst Wohnhaus des Gärtners der Zitronenhäuser, heute ein feines Apartment mit Seeblick und separatem Eingang.","t98b53b16cb":"Wo wir wirklich liegen — und wie man ohne Überraschungen herkommt.","t9d024253d4":"<span class=\"svc-ico\">❄️</span><span class=\"svc-label\">Klimaanlage</span>","t9e43876d88":"<span class=\"room-stat-val\">35m²</span> <span class=\"room-stat-lbl\">Fläche</span>","t9f0d7907bd":"Prà de la Fam · Zimmer","t9f202eff03":"<span class=\"bcs-val\">18 m²</span><span class=\"bcs-lbl\">Fläche</span>","t9f408ceb75":"Das Studio Clementina verfügt über ein Doppelbett, eine praktische, voll ausgestattete Küche und ein großes Bad mit Dusche. Holzmöbel, elegante Details und funktionale Ausstattung machen es besonders behaglich, auch in der Nebensaison. Aus den Fenstern sieht man den See und die Berge ringsum. Der große Privatgarten eignet sich ideal für einen Aperitif, ein Mittagessen im Freien oder zum Entspannen in der Sonne auf den bereitgestellten Liegen.","t9ff4c942e2":"<span class=\"room-stat-val\">2</span> <span class=\"room-stat-lbl\">Max. Gäste</span>","ta0fa0d69d8":"An der Straße Gargnano–Riva del Garda. Kostenlose Privatparkplätze für Gäste.","ta13fa83e74":"Direkt am Wasser liegt das Prà mitten in der Natur. Dahinter erhebt sich eine Felswand mit einem zauberhaften Wasserfall, davor öffnet sich der Blick über den blauen See und den Monte Baldo. Die Familie Parisini führt das Haus seit Jahrhunderten selbst.","ta1dd17aff1":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Voll ausgestattete Küche</span>","ta23177374a":"Wie komme ich mit dem Auto her?","ta3eb0373a9":"Autobahn A4, Ausfahrt Desenzano, Richtung Salò: etwa 15 km. Ab Salò weiter Richtung Riva del Garda auf der Gardesana, der SS 45 bis; hinter Gargnano noch 4 km bis Porto di Tignale.","ta4e82da719":"Sichtstein, freitragende Treppe und eigener Garten","ta505f0bda2":"Vorne der offene See und der Monte Baldo am Veroneser Ufer: An klaren Tagen reicht der Blick von Malcesine bis Sirmione. Dahinter erhebt sich wenige Meter entfernt eine Felswand mit einem Wasserfall.","ta513f6fd85":"<span class=\"svc-ico\">🏡</span><span class=\"svc-label\">Private Freifläche</span>","ta5d6510b68":"Doppelzimmer mit Verbindungstür zu einem Zimmer mit Etagenbett — ideal für Familien mit Kindern.","ta6c3703937":"<span class=\"svc-ico\">🐾</span><span class=\"svc-label\">Haustiere erlaubt</span>","ta86d900f98":"Familie","ta8ab81a313":"<span class=\"rv-name\">🇺🇸 Hua</span><span class=\"rv-date\">Juli 2025 · Doppelzimmer Economy</span>","ta99d92066e":"Das Apartment Bergamotto erstreckt sich über zwei Ebenen. Im Erdgeschoss befinden sich ein Doppelschlafzimmer und ein großes Bad mit Dusche. Im Dachgeschoss liegen der Wohnbereich mit Kochnische und die Möglichkeit für ein drittes Bett. Die Sichtsteinwände und die freitragende Treppe zwischen den beiden Ebenen schaffen eine intime, kühle Atmosphäre.","ta9faca02a1":"Vom nächsten zum entferntesten: Brescia Montichiari, Verona Villafranca, Bergamo Orio al Serio, Mailand Linate, Venedig und Mailand Malpensa.","taa63f05b34":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Seeblick</span>","taab30c2acb":"Ja, Hunde sind willkommen, sowohl in den Zimmern als auch in den Apartments. Der Aufpreis beträgt 10 € pro Nacht und Tier im Hotel und 50 € pro Aufenthalt und Tier in den Apartments — nicht pro Nacht, sondern für den gesamten Aufenthalt.","tab8585e7c5":"Akzeptieren","tabbd679e0c":"Kurz gesagt: ein Zimmer für einen kurzen, unkomplizierten Aufenthalt, ein Apartment für eine Woche, für Familien mit Kindern oder für alle, die einkaufen und selbst kochen möchten.","tabc17b94c9":"Die Limonaia · Ökomuseum","tabe7c8dd16":"<span class=\"svc-ico\">📶</span><span class=\"svc-label\">Kostenloses WLAN</span>","tac18715e60":"Canyoning und Klettern an der Felswand mit dem Wasserfall hinter dem Prà. Für die Mutigeren.","tae509f55e2":"Im historischen Zitronenhaus","taebe065059":"Erhältlich sind sie im Hotel während des Aufenthalts; das gesamte Sortiment sehen Sie auf pradelafam.shop.","tafb272106a":"Apartments","tb07c72fa37":"⚠️ Apartment vorübergehend nicht verfügbar","tb3672026f9":"Erdgeschoss · Separater Eingang","tb3879c037a":"Der beständige Wind lässt Surfer, Kitesurfer und Segler den ganzen Tag aufs Wasser.","tb3e178fcce":"Was sieht man vom Haus aus?","tb498c356db":"<span>Tignale</span><span class=\"dot\">·</span><span>Gardasee</span><span class=\"dot\">·</span><span>Hotel & Apartments</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Ökomuseum Zitronenhaus</span><span class=\"dot\">·</span><span>Windsurfen & Kitesurfen</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>Familie Parisini</span><span class=\"dot\">·</span> <span>Tignale</span><span class=\"dot\">·</span><span>Gardasee</span><span class=\"dot\">·</span><span>Hotel & Apartments</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Ökomuseum Zitronenhaus</span><span class=\"dot\">·</span><span>Windsurfen & Kitesurfen</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>Familie Parisini</span><span class=\"dot\">·</span>","tb4aad9f0d8":"Entdecken","tb6c4ca4ea6":"Große Fenster zum See, voll ausgestattete Küche, Garten mit privater Freifläche. Holzmöbel.","tb6f6d38b2a":"Die Karte","tb7043e80ae":"Das größte und nördlichste Zitronenhaus Europas. Von Ostern bis Oktober zu besichtigen.","tb83f0fe0df":"Kann man baden? Wie ist der Strand?","tb920ed0f41":"Das Studio Kumquat verfügt über ein Doppelbett, eine praktische Kochnische und ein großes Bad mit Dusche. Von innen und vom Privatgarten aus — ideal für einen Aperitif, ein Mittagessen im Freien oder eine Pause auf den bereitgestellten Liegen — genießt man einen großartigen Blick über den See, von Malcesine bis Sirmione.","tba8e493ffa":"Ans Telefon geht die Familie, die das Haus führt. Rufen Sie an oder schreiben Sie: Wir sagen Ihnen, wie es wirklich ist — auch wenn die Antwort lautet «in dieser Woche sind wir ausgebucht».","tba9319bd60":"05 — Wo wir sind","tba9601ab9f":"03 — Zimmer, Apartments und Service","tbb5791de12":"Fabelhaft","tbbc86a325d":"Die <em>Limonaia</em><br>del Prà.","tbe9b82ffd6":"Ohne Farb- und Konservierungsstoffe, aus einer alten örtlichen Brennerei","tbeaaa45bce":"Wandern & MTB","tbf926697bb":"Für Gäste im Zimmer ja, und es ist im Preis enthalten: serviert auf der Veranda, im Schatten der Olivenbäume, mit Blick auf den See.","tbf9a913713":"Autobahn A4, Ausfahrt Brescia Est, Richtung Salò: etwa 20 km. Ab dort wie oben.","tbfadec1a86":"Mit Chili oder Pfeffer. Für Salate, Fisch oder rohes Fleisch","tc00c837bbd":"<span class=\"svc-ico\">♨️</span><span class=\"svc-label\">Mikrowelle</span>","tc058c4cdc9":"Das Studio Calamondino bietet dank großer Fenster einen herrlichen Seeblick. Es verfügt über ein Doppelbett, eine Kochnische und ein Bad mit Dusche. Holzmöbel, sorgfältige Details und funktionale Ausstattung machen es besonders komfortabel, vor allem in der Nebensaison. Draußen ist der große Privatgarten perfekt für einen Aperitif, ein Mittagessen im Freien oder zum Entspannen in der Sonne auf den bereitgestellten Liegen.","tc16b56a0bd":"Für ruhigere Tage: Gargnano wenige Kilometer entfernt, Limone sul Garda und Riva del Garda im Norden, die Wallfahrtskirche Montecastello oberhalb von Tignale.","tc3244756f3":"Tignale liegt im Park Alto Garda Bresciano und bewahrt neben den Parkwegen ein dichtes Netz von Militärpfaden — von den Karten längst vergessen — die Schützengräben, Unterstände, Stollenstellungen und Kasematten verbinden. Fast immer an den aussichtsreichsten Stellen.","tc3be219c28":"<span class=\"bcs-val\">2 Pers.</span><span class=\"bcs-lbl\">Belegung</span>","tc4e9ccf33d":"Suchen →","tc4f2d54efd":"Eigenes Bad mit Dusche, Föhn, Handtuchset, Duschgel und Kosmetikset; Klimaanlage, kostenloses WLAN, Fernseher und ein leerer Kühlschrank zur freien Verfügung.","tc51398d85e":"<span class=\"room-stat-val\">23m²</span> <span class=\"room-stat-lbl\">Fläche</span>","tc5f475fec9":"<span class=\"bcs-val\">3 Pers.</span><span class=\"bcs-lbl\">Belegung</span>","tc5fad9b6ee":"<span class=\"room-stat-val\">65m²</span> <span class=\"room-stat-lbl\">Fläche</span>","tc63a6303e9":"Das ist keine für Besucher wiederaufgebaute Limonaia: Sie lebt und trägt Früchte, aus denen die in Salz eingelegten Zitronen, der Limoncino und der Sirup entstehen, die man am Ende der Führung probiert.","tc6ae6580d2":"Gäste","tc76eb4a334":"Erster und zweiter Stock","tcb93134e47":"Es fühlt sich an wie Nachhausekommen. Der Ort ist bezaubernd, mitten in der Natur, und der See ist herrlich.","tcc609e0585":"<span class=\"svc-ico\">🌳</span><span class=\"svc-label\">Privatgarten</span>","tcd38f168ec":"Prà de la Fam® ist eine in Italien eingetragene Marke der FAM S.r.l.","tce08c37a2c":"Echte Erfahrungen von Gästen, die im Prà de la Fam übernachtet haben.","tceef27f1f7":"Was ist die Limonaia del Prà de la Fam, und kann man sie besichtigen?","tcf268eb913":"Bewertungen","tcf4012d7d5":"Im Hotel → Entdecken","td0bf44ac3a":"Die Umgebung","td0bffd1f6d":"Tassen & Accessoires","td0c5b92b23":"Die Apartments tragen den Namen einer Zitrusfrucht aus der Limonaia. Die Klementine ist die Kreuzung aus Orange und Mandarine.","td0e7331b28":"Windsurfen & Kitesurfen","td122cacdeb":"Das alte Haus des Gärtners. Separater Eingang, Seeblick, Kochnische. Wenige Schritte vom Strand.","td1523d1952":"Doppelzimmer Standard","td1f30cb50f":"Apt. Kumquat","td2f58fcd68":"<span class=\"bcs-val\">16 m²</span><span class=\"bcs-lbl\">Fläche</span>","td4b6fcbd5b":"Von Osten","td5068d47a5":"Wie bucht man? Lohnt es sich, direkt über die Website zu buchen?","td62becd9e0":"Geben Sie «Prà de la Fam» oder «Porto di Tignale» ein. Nicht nur «Tignale»: Das Navi führt Sie hinauf ins Dorf auf dem Berg, und von dort müssen Sie wieder hinunter.","td96b889af3":"Folgen Sie uns","td97b396efc":"Das Wesentliche, unschlagbare Lage","tdac219b4c6":"Wandern und Mountainbiken beginnen direkt vor der Tür: Wir liegen im Naturpark Alto Garda Bresciano, und neben den Parkwegen gibt es ein dichtes Netz alter Militärpfade — Schützengräben, Unterstände, Stollen und Kasematten —, längst von den Karten verschwunden und fast immer an den schönsten Aussichtspunkten.","tdd0355ae67":"Luftige Doppelzimmer mit Blick auf den Gardasee und die umliegenden Berge.","tdd63715330":"Die Führung erzählt, wie die Zitronengärten des Gardasees funktionierten: die Steinpfeiler, die Bretter, die das Gewächshaus im Winter schlossen, der Zitronenhandel nach Nordeuropa. Zum Abschluss gibt es eine Verkostung der hier entstehenden Produkte: in Salz eingelegte Zitronen, Limoncino, Zitronensirup und Zitrusöl. Zeiten und Informationen auf der eigenen Website ecomuseopradelafam.com.","tde4616b554":"Das hängt davon ab, wie lange Sie bleiben und wie viel Sie kochen möchten. Es gibt zehn Zimmer: Doppelzimmer Standard (18 m²), Doppelzimmer Economy (16 m²), Dreibettzimmer (23 m²) und Familienzimmer (29 m²), alle mit eigenem Bad, Klimaanlage, WLAN und inbegriffenem Frühstück auf der Veranda. Für zwei oder drei Nächte ist das die einfachste Wahl.","tdedb012719":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WLAN</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Familien</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Eigenes Bad</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Frühstück</span>","tdef993fa85":"<span class=\"svc-ico\">🚗</span><span class=\"svc-label\">Kostenlose Parkplätze</span>","tdf027beffb":"Zitrone und Bitterorange. Latteria Turnaria di Tignale","tdf45fca4d2":"<span class=\"rv-name\">🇵🇱 Grzegorz</span><span class=\"rv-date\">2025 · Polen</span>","tdf7cb322cf":"Studio mit großen Fenstern zur Limonaia, voll ausgestatteter Küche und privater Freifläche.","te212539cb8":"Zimmer buchen →","te292d68d63":"Apt. Bergamotto","te2cfa28881":"<span class=\"room-stat-val\">18m²</span> <span class=\"room-stat-lbl\">Fläche</span>","te3f65a8ce9":"Die Limonaia des Prà de la Fam wurde 1985 mit Unterstützung der Comunità Montana des Parks Alto Garda Bresciano restauriert. Die 80 ausgewachsenen Bäume bilden heute das Ökomuseum, von Ostern bis Oktober zu besichtigen.","te570deba88":"04 — Sport & Natur","te594ea220c":"Wo","te5cc02c791":"<span class=\"room-stat-val\">3</span> <span class=\"room-stat-lbl\">Max. Gäste</span>","te5de2cbb0d":"Prà de la Fam · Apartment","te5e331d5c9":"Die Limonaia","te6b441803d":"<span class=\"svc-ico\">📺</span><span class=\"svc-label\">Fernseher</span>","te6e178ccc8":"Cookie-Richtlinie","te8106f1430":"Fantastische Lage, eine kleine Perle am Gardasee. Matteo, Eigentümer und Gastgeber, ist überaus freundlich und hat uns viel erzählt und empfohlen. Exklusive Lage, ein wunderschöner und bezaubernder Ort — ich würde tausendmal wiederkommen. Privater, abgeschlossener Parkplatz (super für Motorradfahrer wie mich) und neue Fenster: null Lärm im Zimmer.","te8c99f06b1":"Hotel und Apartments direkt am Gardasee, in der nördlichsten historischen Limonaia Europas. Im Rücken ein Wasserfall im Fels, vorne der blaue See — wo die Zeit stillsteht.","teb07e74228":"02 — Die Lage und die Zitronengärten","tec5181be2c":"Das sind die Fragen, die uns wirklich am Telefon und an der Rezeption gestellt werden, ausführlich beantwortet — genauso, wie wir es persönlich täten. Wenn Ihre Frage fehlt, rufen Sie an: Sie erreichen uns, keine Telefonzentrale.","tecb5de2726":"Die Touren starten zu Fuß direkt am Hotel: Wege des Parks Alto Garda und historische Militärpfade mit weitem Blick.","ted709911db":"Luftig, modern, See- oder Bergblick","tede794f1e2":"03 — Ökomuseum","tef84d416a9":"Mit dem Zug","tefcd26e01b":"Wo<br><em>wir sind</em>","tf03b6bab86":"Für die Apartments nicht, denn sie haben eine Küche: Wer möchte, kann es gegen Aufpreis dazubuchen. Sagen Sie einfach bei der Buchung Bescheid — oder auch am Vortag an der Rezeption.","tf08ba2a641":"Unser<br><em>Anwesen</em>","tf11b96d58c":"Die Zimmer haben je nach Lage im Haus See- oder Bergblick; die Apartments blicken alle auf den See. Das Frühstück wird auf der Veranda serviert, im Schatten der Olivenbäume, mit dem See vor sich.","tf1c8b4462a":"Mit dem Auto","tf2137a9a21":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Kühlschrank</span>","tf27cd0f01e":"<span class=\"svc-ico\">💨</span><span class=\"svc-label\">Haartrockner</span>","tf297f278b2":"In Tignale gelegen, einem typischen Dorf am Gardasee an der Straße nach Riva, wenige Kilometer von Gargnano entfernt, bietet das Prà de la Fam die ideale Lage für einen ruhigen oder sportlichen Urlaub.","tf3822d6248":"Wie ist die Straße? Ich habe gelesen, sie sei eng und voller Tunnel.","tf38421c0d2":"Via Gardesana, 7 · Sponda bresciana<br>Straße Gargnano–Riva del Garda","tf4467cd18b":"Fragen","tf561d3c688":"Das alte Haus des Gärtners, wiedererweckt","tf5795ea6fe":"Blick von Malcesine bis Sirmione, Privatgarten mit Liegen. Kochnische, Bad mit Dusche.","tf757da1422":"Die Natur","tf946f40316":"Zimmer","tfc36cf0b38":"Windsurfen, Kitesurfen und Segeln: Der Wind am Gardasee ist beständig und regelmäßig, und der Circolo Vela Gargnano veranstaltet die ganze Saison über Regatten, darunter die historische Centomiglia.","tfde24d0272":"Zweizimmer-Apartment auf zwei Ebenen mit Sichtstein, freitragender Treppe und eigenem Garten. Das großzügigste des Anwesens.","tfe69b1ca69":"Zwei Verbindungszimmer für die ganze Familie","tfe6bf92cf4":"Das Anwesen gehört weiterhin der Familie Parisini. Bei den Führungen erfahren Sie die Geschichte und die Besonderheiten der Limonaia, zum Abschluss lädt eine Verkostung zur Entdeckung der Produkte ein: Zitronen in Salz, Limoncino, Zitronensirup und Zitrusöl.","tff0a201186":"Limoncino-Likör","tff12d938aa":"Online buchen","tff9b24f4c2":"Die Apartments sind in der alten Limonaia entstanden: Clementina, Calamondino, Kumquat und Pomelo bieten rund 35 m² für zwei Personen, mit voll ausgestatteter Küche oder Kochnische, Außenbereich und Seeblick; Bergamotto liegt auf zwei Ebenen, 65 m², ist derzeit aber nicht verfügbar.","tffdf35b0f8":"Sind Hunde erlaubt?"},"fr":{"t002b752f7c":"Trois couchages, salle de bain privée, idéale pour des groupes d'amis ou des familles avec un enfant. Accès direct au jardin et à la plage.","t00d3f340d3":"Perché au-dessus du lac de Garde, Tignale est une destination renommée du tourisme international.","t00dda435d9":"Réserver →","t0157951bb7":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Vue montagne</span>","t0268fb0ea8":"Vous n'avez pas trouvé votre réponse ?","t02b83bc7a6":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Vue jardin</span>","t04268fbc76":"Escalade","t044ccabb57":"<span class=\"svc-ico\">🚿</span><span class=\"svc-label\">Douche</span>","t049011f98d":"Les appartements portent le nom d’un agrume de la limonaia. Le calamondin est une petite mandarine, très juteuse et sucrée.","t0794554adf":"Grandes baies vitrées, lumière du lac, jardin","t085726e29d":"Tignale · Via Gardesana, 7 · Porto di Tignale · Lac de Garde","t092ab3f505":"Une fois sur place, on se passe très bien de voiture : plage, limonaia et sentiers partent de la porte. Pour visiter les autres villages du lac, en revanche, la voiture ou le bateau sont utiles.","t09ef86ca9b":"Services inclus","t0a015b54e8":"Départ","t0a1b390212":"Galerie photos","t0aae14be2b":"En venant du nord : gare de Rovereto, bus jusqu’à Riva del Garda puis la ligne vers Gargnano.","t0ce18bb3ab":"Visitez ecomuseopradelafam.com →","t0ec5e15397":"<span class=\"svc-ico\">🥐</span><span class=\"svc-label\">Petit-déjeuner inclus</span>","t0f15cc4caa":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Coin cuisine</span>","t0f44bbc76e":"<span class=\"bcs-val\">29 m²</span><span class=\"bcs-lbl\">Surface</span>","t0f9627b57b":"<span class=\"rv-name\">🇮🇹 Tommaso</span><span class=\"rv-date\">Août 2024 · Chambre Double</span>","t0ffeeaad93":"posées à la réception.","t116994d1f1":"Oui. Les gares pratiques sont Brescia et Desenzano–Sirmione, sur la ligne Milan–Venise ; de là partent les bus qui longent la Gardesana, plus fréquents depuis Brescia, plus rares depuis Desenzano. On descend à l'arrêt « Porto di Tignale », juste devant chez nous.","t119436bb10":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Espace extérieur</span>","t12e5204303":"Le petit-déjeuner est-il inclus ?","t134b097f44":"Vaut-il mieux une chambre d'hôtel ou un appartement ?","t1475215d61":"Ce que l'on voit d'ici, et ce qu'est vraiment cette limonaia.","t163ba9bcc4":"Chambres doubles lumineuses et confortables, au premier ou au deuxième étage de l'hôtel. Certaines offrent une vue exclusive sur le lac de Garde, d'autres associent une belle vue sur le lac et les montagnes environnantes, selon leur position dans le bâtiment. Le mobilier est moderne et accueillant. Inclus : climatisation, Wi-Fi gratuit, TV, réfrigérateur vide et parking réservé gratuit. Les salles de bain disposent d'une douche, d'un sèche-cheveux, d'un jeu de serviettes, de gel douche et de produits d'accueil.","t1672e78ca1":"Vérifier les disponibilités →","t16ef7fdba4":"Bois, pierre et silence dans la limonaia historique","t16f921ca52":"Où nous sommes","t177195854b":"Vue de Malcesine à Sirmione, jardin privé","t189b807e55":"Les chambres doubles economy, au premier et au deuxième étage de l'hôtel, sont un peu plus compactes mais tout aussi confortables. Toutes offrent une vue sur le lac de Garde et sont meublées dans un style moderne et accueillant. Climatisation, TV, Wi-Fi gratuit et réfrigérateur vide. La salle de bain, récemment rénovée, dispose d'une douche, d'un sèche-cheveux, d'un jeu de serviettes, de gel douche et de produits d'accueil. Parking réservé gratuit inclus.","t1a4e01727f":"Pressée à froid. Également disponible aux agrumes","t1acc2b334c":"Nous n'avons pas de piscine, et elle ne nous a jamais manqué : ici, on se baigne dans le lac.","t1afd65f4cd":"Contact","t1e5e550e0d":"Sur le lac de Garde, les limonaie historiques sont nombreuses, mais presque toutes sont des structures vides : les piliers et les murs restent, pas les arbres. La nôtre est encore cultivée, et c'est la plus grande et la plus septentrionale d'Europe — elle pousse exactement à la limite climatique au-delà de laquelle un citronnier ne tient plus en plein air.","t1e65935b2b":"Italien, anglais, allemand, français et espagnol, à la réception comme sur tout le site. La famille gère l'établissement en personne : celui qui répond au téléphone est celui qui vous accueillera à l'arrivée.","t1f0dbd96ab":"Chambres","t1f3d2afb49":"Chambre double avec salle de bain privée, vue lac ou jardin. Mobilier soigné, fenêtres neuves sans bruit. Petit-déjeuner inclus en véranda.","t207ef0e5ad":"Que dois-je saisir dans le GPS ?","t21a221f032":"<span class=\"svc-ico\">✨</span><span class=\"svc-label\">Ménage de fin de séjour</span>","t21de8404dc":"Voile","t21e4cfe334":"Chambre · Prà de la Fam","t226b000df2":"Explorez la propriété : hôtel, appartements, limonaia, sentiers et parking. Survolez les points pour découvrir les détails.","t23d419716f":"En réservant en direct, vous parlez avec nous et non avec un intermédiaire : les demandes particulières — le chien, le petit-déjeuner en appartement, l'arrivée tardive, une chambre près du jardin — se règlent en deux lignes de courriel.","t251c5c5589":"Hébergements","t25fcc2c679":"Peut-on venir sans voiture, en train ou en avion ?","t2768309b26":"Quelles langues parlez-vous ?","t277537d39c":"Huile d'olive extra vierge bio","t2779f6af30":"Pour qui séjourne ici, la différence pratique est simple : la limonaia n'est pas une excursion à programmer, c'est le jardin à côté de la chambre. Et les cinq appartements sont aménagés dans l'ancienne limonaia, au point de porter chacun le nom d'un agrume : Clementina, Calamondino, Kumquat, Pomelo, Bergamotto.","t27c22ff3e6":"Cookies &amp;amp; confidentialité","t282d4f9757":"Chambre Double","t29439a78d2":"Prêt à<br><em>réserver ?</em>","t294fe37686":"Hôtel — 10 chambres","t2a3ace25d3":"01 — La route et l'arrivée","t2adafad680":"Nous sommes à votre disposition pour toute information.","t2b2d8e27c6":"Huile d'olive extra vierge bio, vêtements et accessoires au logo du Prà de la Fam. Disponibles à l'hôtel pendant votre séjour.","t2c4531f1c4":"Huile d'olive extra vierge du Garda","t2cdeef2a77":"<span class=\"bcs-val\">23 m²</span><span class=\"bcs-lbl\">Surface</span>","t303332408e":"<span class=\"svc-ico\">🚪</span><span class=\"svc-label\">Salle de bain privée</span>","t303af58209":"Depuis l’ouest","t30de35ddfd":"Prà de la Fam · Informations","t310e4bca25":"Les chambres triples, au premier et au deuxième étage de l'hôtel, ont été récemment rénovées et offrent une splendide vue sur le lac de Garde. Meublées dans un style moderne, elles disposent de tout le confort gratuit : télévision, climatisation, réfrigérateur vide et Wi-Fi. Les salles de bain, entièrement neuves, sont spacieuses avec douche, sèche-cheveux et produits d'accueil.","t3182984c6c":"L'arrivée se fait de 14h00 à 20h00, le départ avant 10h30.","t321480eea5":"⚠️ L'appartement se trouve dans la limonaia historique et s'atteint par de nombreuses marches : il ne convient pas aux personnes à mobilité réduite.","t33651bcbf3":"Quelle différence entre votre limonaia et les autres du lac de Garde ?","t33c92d054c":"Le bouton « Réserver » du site ouvre notre moteur de réservation, avec les disponibilités en temps réel et la confirmation immédiate. Vous pouvez aussi appeler le (+39) 0365 799890 ou écrire à info@alpradelafam.com.","t342c9c14f0":"Les sentiers oubliés","t34dc9f10fe":"Avis<br><em>de nos clients</em>","t34e09946bd":"<span class=\"rv-name\">🇵🇱 Tomek</span><span class=\"rv-date\">Juin 2025 · Chambre Double Economy · 7 nuits</span>","t35323ab850":"C'est vrai, et c'est aussi ce qui rend le trajet mémorable. La Gardesana Occidentale est taillée dans la roche au-dessus du lac : étroite, avec de nombreux tunnels, dont certains s'ouvrent sur l'eau. C'est l'une des routes les plus panoramiques d'Italie.","t35e33176d7":"Oui, le parking est privé, gratuit et réservé aux clients, juste devant l'établissement. Il est fermé, donc parfait aussi pour les motos — c'est l'un des points que les motards citent le plus souvent dans leurs avis.","t36cd9798d3":"Cuisine équipée, mobilier en bois. Vue lac et jardin.","t36f6028b9b":"<span class=\"bcs-val\">65 m²</span><span class=\"bcs-lbl\">Surface</span>","t373f10061d":"Les appartements portent le nom d’un agrume de la limonaia. La bergamote donne l’huile essentielle qui est à la base de l’eau de Cologne.","t37593677ae":"Où se trouve exactement le Prà de la Fam ?","t376351c53f":"<span class=\"apt-feat\">A/C</span><span class=\"apt-feat\">Cuisine</span><span class=\"apt-feat\">Wi-Fi</span><span class=\"apt-feat\">Lit double</span>","t37c41cd8c9":"Espace et confort pour trois, face au lac","t37c595f16c":"Nécessaires uniquement","t380557569e":"Autoroute du Brenner A22, sortie Rovereto Sud, direction Riva del Garda, puis la Gardesana vers Brescia sur une vingtaine de kilomètres.","t38b0016ada":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Wi-Fi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Salle de bain privée</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Petit-déjeuner</span>","t398dc61e6a":"Téléphone","t3ba43a112b":"Région & Sport","t3bb12c5cc5":"Depuis l'ouest : autoroute A4, sortie Brescia Est, direction Salò, environ 20 km, puis comme ci-dessus.","t3c7ffbd79b":"Emportez le lac<br><em>avec vous.</em>","t3ca4a501a2":"T-shirts & Sweats","t3e3e2e7ec7":"📞 Appeler : +39 0365 799890","t3e669ed4d0":"Oui. Huile d'olive extra vierge biologique pressée à froid, huile aux agrumes, citrons au sel au piment ou au poivre, limoncino sans colorants ni conservateurs, sirop de citron et confitures biologiques de citron et d'orange amère, ainsi que des vêtements et accessoires au logo du Prà.","t3e730c4314":"Sur la même propriété se trouve la Limonaia del Prà de la Fam : la plus grande et la plus septentrionale d'Europe, quatre-vingts arbres encore en production, visitable de Pâques à octobre. C'est ce qu'aucun autre hôtel du lac de Garde ne possède — et les cinq appartements sont aménagés là, dans l'ancienne limonaia.","t3f0a50c945":"Nous vous demandons simplement de le signaler à la réservation, afin de vous attribuer le logement le plus pratique. Tout autour il y a le jardin, la plage est libre et les sentiers du parc partent de la porte : pour un chien, c'est un endroit facile.","t3f47d99b7d":"Studio avec lit double, cuisine et jardin privé avec vue panoramique sur le lac.","t3f59fc3c84":"Studio avec cuisine équipée, mobilier en bois et grand jardin privé.","t405e497d1d":"220 avis vérifiés · Booking.com","t4067735dc5":"<span class=\"room-stat-val\">4</span> <span class=\"room-stat-lbl\">Personnes max</span>","t409c8e4975":"Adresse","t41bc46e952":"C'est la plus grande et la plus septentrionale des limonaie d'Europe, et elle se trouve à l'intérieur de notre propriété : depuis la chambre, on y est en une minute à pied. Ce n'est ni une ruine ni une reconstitution — les quatre-vingts arbres adultes sont vivants et en production.","t41c8f32a08":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Réfrigérateur vide à disposition</span>","t4353996ec1":"<span class=\"svc-ico\">☀️</span><span class=\"svc-label\">Terrasse</span>","t43a4b78b40":"Découvrir les appartements","t43d51909d4":"Disponibilités en temps réel avec notre moteur de réservation. Confirmation immédiate.","t44013397ef":"Oui. La plage est à moins de vingt mètres du jardin : on traverse la pelouse et on est dans l'eau. C'est une petite plage libre, pas un lido aménagé : ni rangées de parasols, ni portails.","t44e1690ba5":"Qu'y a-t-il dans la chambre ?","t4822dcbf95":"<span class=\"room-stat-val\">16m²</span> <span class=\"room-stat-lbl\">Surface</span>","t486b047c5e":"Nous utilisons des cookies analytiques pour comprendre l'usage du site et l'améliorer. Aucune donnée n'est cédée à des tiers à des fins publicitaires.","t48a4ee031f":"Elle se parcourt normalement en voiture, à moto et en camping-car — les autocars de ligne y passent tous les jours — à condition d'aller doucement et de ne pas être pressé lors des croisements en tunnel. Le conseil que nous donnons à tous : prévoir une demi-heure de plus et s'arrêter dans l'une des aires : de là-haut, on voit tout le lac.","t49218f6b75":"Inutile de le réserver ou de le signaler à l'avance : il y a de la place pour tous les clients.","t49448908e0":"<span class=\"room-stat-val\">🌊</span> <span class=\"room-stat-lbl\">Vue lac</span>","t4a7cce2b7a":"Un hôtel avec<br><em>un emplacement idéal.</em>","t4da9c9af96":"Chambre","t507171eb65":"Récemment rénovée, avec vue lac et tout le confort pour trois personnes.","t51b9fc85e9":"Questions fréquentes","t52ec2ad3f5":"En voiture, en train, en avion","t52fef421c2":"Ouvrir dans Google Maps →","t548a496993":"Que peut-on faire dans les environs ?","t558bacaaaa":"Appartement · Prà de la Fam","t55de887092":"Boutique","t5624b2aeef":"Nos<br><em>appartements</em>","t5688e3684d":"Le lac est ici propre et profond ; la saison de baignade va grosso modo de juin à septembre. Le matin l'eau est un miroir, l'après-midi le vent se lève — c'est pourquoi la portion devant nous est fréquentée par les véliplanchistes et les kitesurfeurs.","t59f7f88684":"<span class=\"svc-ico\">🛎️</span><span class=\"svc-label\">Linge inclus</span>","t5acc558e2c":"<span class=\"svc-ico\">🚭</span><span class=\"svc-label\">Non-fumeur</span>","t5be0bd6124":"Tous reliés en train ou en bus aux gares de Brescia, Desenzano et Vérone, d’où l’on poursuit le long de la Gardesana.","t5c40bb1a86":"06 — Ce qu'ils en disent","t5e16e39fef":"Canyon Adventures — spécialistes du canyoning sur le Garda depuis plus de 20 ans. Canyons du Garda et Valle di Ledro.","t5f01edbe54":"<span class=\"room-stat-val\">29m²</span> <span class=\"room-stat-lbl\">Surface</span>","t5ff2e24a05":"Nos <em style=\"font-style:italic;color:var(--gold-titolo)\">chambres</em>","t606dccfdd7":"Depuis l'est : autoroute A4, sortie Desenzano, direction Salò, environ 15 km. De Salò, continuer vers Riva del Garda sur la Gardesana, la SS 45 bis ; après Gargnano, encore 4 km jusqu'à Porto di Tignale.","t610f5e52ac":"Prà de la Fam, lac de Garde","t616fa8aab9":"<span class=\"bcs-val\">35 m²</span><span class=\"bcs-lbl\">Surface</span>","t6649158d5f":"Rez-de-chaussée + combles · Entrée par le sentier Oldesio","t67275fe941":"Depuis le nord","t686954d940":"Le dernier tronçon avant chez nous est un tunnel : l'entrée du Prà de la Fam arrive juste après, sur la droite si vous venez de Gargnano.","t6887a8d847":"Autrefois demeure du jardinier des limonaie, Pomelo est aujourd'hui un appartement raffiné d'environ 35 m² qui allie charme historique et confort moderne. Il dispose d'une entrée privée, d'un séjour avec coin cuisine équipé, d'une chambre double lumineuse avec vue sur le lac de Garde et d'une salle de bain moderne. À quelques pas de la plage, Pomelo offre un séjour intime et serein, idéal pour ceux qui recherchent nature, silence et romantisme dans un cadre authentique.","t69ca9b15cf":"Ce que l'on demande à la réception avant de réserver.","t6a5f93783c":"<span class=\"rv-name\">🇮🇹 Antonella</span><span class=\"rv-date\">Août 2024 · Chambre Familiale · 3 nuits</span>","t6b0e874d96":"Une batterie d’artillerie, avec ses tranchées et ses bunkers de protection, s’étend sur tout le Monte Castello, près du sanctuaire et sur les versants nord. Les lignes défensives, dont les vestiges restent bien visibles, se poursuivent le long du Dosso Piemp — près du Rifugio degli Alpini — jusqu’au Passo della Puria et aux limites de la commune.","t6b6fcba8ff":"Confitures bio","t6bafccbf5c":"<span class=\"apt-feat\">Vue lac</span><span class=\"apt-feat\">Cuisine</span><span class=\"apt-feat\">Jardin</span><span class=\"apt-feat\">A/C</span>","t6bedaf9568":"Très spacieuse, avec plusieurs couchages, pensée pour les familles avec enfants. Grande salle de bain privée avec douche spacieuse. Vue sur le jardin et accès à la plage.","t6d55b5df46":"L'ancienne limonaia du Prà accueille aujourd'hui cinq appartements studio ou deux-pièces, meublés avec goût et élégance.","t6e341fb57d":"Exceptionnel.","t6e616acee6":"Triple","t6ea05b015c":"La Gardesana est étroite et pleine de tunnels, mais c’est l’une des routes les plus panoramiques d’Italie : prenez le temps de la regarder.","t6f4a1eab99":"Les gares pratiques sont Brescia et Desenzano–Sirmione, sur la ligne Milan–Venise. Depuis Brescia les bus le long de la Gardesana sont plus fréquents, depuis Desenzano plus rares. On descend à l’arrêt Porto di Tignale.","t70f8bb9a8a":"Accueil","t71f872c875":"<span class=\"svc-ico\">🧴</span><span class=\"svc-label\">Produits d'accueil</span>","t7223c24b87":"Elle a été restaurée en 1985 avec la Comunità Montana du Parc Alto Garda Bresciano et constitue aujourd'hui un Écomusée, visitable de Pâques à octobre. Elle est restée la propriété de la famille Parisini, celle-là même qui dirige l'hôtel.","t75609dc75e":"Depuis le nord : autoroute du Brenner A22, sortie Rovereto Sud, direction Riva del Garda, puis la Gardesana vers Brescia sur une vingtaine de kilomètres. L'entrée donne directement sur la Gardesana, avec le parking devant : aucune route de montagne à affronter au dernier moment.","t75b631c58e":"On les rejoint par les anciennes routes militaires restées en altitude : on roule jusqu’où les pistes sont praticables, puis on continue à pied ou en VTT sur les vieux sentiers d’accès.","t75efd8f58e":"Fondé en 1912, 18 trous de grande tradition entre Gargnano et Toscolano Maderno. Troisième golf club d'Italie.","t7629980224":"Vérifier les disponibilités →","t7730c4bbfd":"Découvrir la Bottega →","t7781fce007":"<span class=\"bcs-val\">4 pers.</span><span class=\"bcs-lbl\">Capacité</span>","t778369e4af":"Le Circolo Vela Gargnano organise des régates chaque saison. La traditionnelle Centomiglia est l'événement à la voile le plus attendu du Garda.","t77d524feeb":"<span class=\"rv-name\">🇮🇹 Francesco</span><span class=\"rv-date\">Mai 2025 · Chambre Double Economy</span>","t785a762e36":"À quelle heure se font l'arrivée et le départ ?","t7886c29db5":"<span class=\"svc-ico\">🛏️</span><span class=\"svc-label\">Lit double</span>","t79f323fa30":"Uniquement à l'hôtel → Découvrir","t7bf6f8745f":"Serviette & Tongs","t7d590f39bd":"Appartement","t7d6fd5e619":"02 — Les appartements","t7dc7c098bb":"<span class=\"svc-ico\">🌊</span><span class=\"svc-label\">Vue lac</span>","t7f8cf18395":"Région &<br><em>Activités</em>","t8086d463dc":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Wi-Fi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Salle de bain privée</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Petit-déjeuner</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">A/C</span>","t82253c0699":"Si vous arrivez après 20h00, appelez-nous : l'établissement est familial et nous nous organisons, il suffit de le savoir à l'avance. Et si vous arrivez en avance, vous pouvez en général laisser la voiture au parking et profiter du jardin et de la plage pendant que nous terminons la chambre.","t8260aa1fca":"Le petit-déjeuner est servi sous la véranda, à l’ombre des oliviers, et le grand jardin est l’endroit idéal pour rester au soleil. La plage est à moins de vingt mètres.","t838f87a25f":"Une cascade de roche derrière, le lac et le Monte Baldo devant. Une limonaia en activité à deux pas.","t84add5b295":"E-mail","t84e7696a19":"Arrivée","t85057929c4":"En avion","t85d43acc19":"08 — Venez nous voir","t86061d940c":"Directement sur le lac. Une cascade de roche derrière, le lac bleu et le Monte Baldo devant.","t860cb7ff5c":"Les aéroports, du plus proche au plus lointain : Brescia Montichiari, Vérone Villafranca, Bergame Orio al Serio, Milan Linate, Venise et Milan Malpensa, tous reliés en train ou en car à Brescia, Desenzano et Vérone.","t861e60c1c5":"Sur deux niveaux : chambre double et salle de bain au rez-de-chaussée, séjour avec cuisine sous les combles. Intérieurs en pierre apparente avec escalier en porte-à-faux caractéristique.","t865919f6fc":"Le choix idéal pour profiter du lac de Garde au meilleur rapport qualité-prix. Salle de bain privée, confort essentiel, emplacement imbattable.","t87da551950":"Bienvenue<br><em>Al Prà</em><br>de la Fam.","t888a00e0c1":"Comment venir","t888f0dc89c":"Réserver","t8920e8076f":"Les appartements portent le nom d’un agrume de la limonaia. Le pomélo est l’une des trois espèces dont descendent tous les agrumes : contrairement aux autres il n’est pas sphérique, et a souvent la forme d’une poire.","t8943b36bd7":"Y a-t-il un parking ? Est-il payant ?","t89992fa817":"Peut-on acheter vos produits ?","t89d8242e92":"Située au premier ou au deuxième étage de l'hôtel, la chambre familiale se compose d'une chambre double communicante avec une chambre à lits superposés, idéale pour les familles avec enfants. Les espaces ont été récemment rénovés avec un mobilier moderne et accueillant. La chambre double offre une vue saisissante sur le lac, tandis que la seconde donne sur le versant de la montagne, garantissant calme et intimité. La salle de bain est spacieuse, avec grande douche, sèche-cheveux et produits d'accueil. La chambre dispose de tout le confort : climatisation, TV à écran plat, réfrigérateur vide, Wi-Fi gratuit et kit de bienvenue. L'accès au parking privé de l'hôtel est inclus.","t8a9cf1c412":"Chambre Double Economy","t8bc3f4c3b5":"Chambre Familiale","t8c79b16206":"Toutes les fenêtres ont été refaites : de la Gardesana, qui passe juste devant, aucun bruit n'entre dans les chambres — c'est l'un des points que les clients citent le plus souvent. L'établissement est non-fumeurs.","t8e20ae8c0a":"<span class=\"apt-feat\">Vue lac</span><span class=\"apt-feat\">Entrée privée</span><span class=\"apt-feat\">Coin cuisine</span><span class=\"apt-feat\">A/C</span>","t908bad1849":"Réserver →","t90eab9b683":"Une chose déroute presque tout le monde, et mieux vaut le savoir avant de partir : le village de Tignale se trouve en haut, sur la montagne, à quelques kilomètres de lacets de la rive. Nous sommes en bas, au bord du lac, sur la Gardesana. Les coordonnées exactes sont 45°43.684′N · 10°43.176′E.","t91922be9e2":"Citrons au sel","t919de81cb1":"Puis le canyoning dans les gorges du Garda et du Val di Ledro, l'escalade sur la paroi derrière l'hôtel, et le Golf Bogliaco, fondé en 1912, troisième golf club d'Italie, entre Gargnano et Toscolano Maderno.","t92138ee587":"Chambre Triple","t93167e8876":"01 — Notre histoire","t9324d6f296":"Prà de la Fam —<br><em>Lac de Garde</em>","t9363a07ad5":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Wi-Fi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">3 couchages</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Salle de bain privée</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Petit-déjeuner</span>","t937faf91fe":"Nous sommes Via Gardesana 7, Porto di Tignale, 25080 Tignale (BS) : rive bresciane du lac de Garde, sur la route qui relie Gargnano à Riva del Garda. L'établissement est directement au bord du lac — la plage est à moins de vingt mètres du jardin.","t961e629f7e":"Double Economy","t965334bacd":"Les appartements portent le nom d’un agrume de la limonaia. Le kumquat, ou mandarine chinoise, donne des fruits très sucrés, gros comme une orange miniature.","t96945f98b8":"Le choix idéal pour vivre le lac de Garde au meilleur rapport qualité-prix.","t96a929601b":"Hôtel et appartements sur le lac de Garde.<br>Via Gardesana, 7 · Porto di Tignale · 25080 Tignale (BS)","t977804b6aa":"Excellent point de départ pour visiter tout ce côté du lac. Vue magnifique avec accès à une petite plage, chambre propre et personnel très gentil.","t98513048a0":"Si vous préférez la sécurité, entrez directement les coordonnées 45°43.684′N · 10°43.176′E, ou ouvrez notre position sur Google Maps depuis la page contacts.","t9885da33e4":"Autrefois demeure du jardinier des limonaie, aujourd'hui un appartement raffiné avec vue lac et entrée privée.","t98b53b16cb":"Où nous sommes vraiment, et comment arriver sans surprises.","t9d024253d4":"<span class=\"svc-ico\">❄️</span><span class=\"svc-label\">Climatisation</span>","t9e43876d88":"<span class=\"room-stat-val\">35m²</span> <span class=\"room-stat-lbl\">Surface</span>","t9f0d7907bd":"Prà de la Fam · Chambre","t9f202eff03":"<span class=\"bcs-val\">18 m²</span><span class=\"bcs-lbl\">Surface</span>","t9f408ceb75":"Le studio Clementina dispose d'un lit double, d'une cuisine équipée pratique et d'une grande salle de bain avec douche. Le mobilier en bois, les finitions élégantes et l'équipement fonctionnel le rendent particulièrement accueillant, même en demi-saison. Des fenêtres on voit le lac et les montagnes alentour. Le grand jardin privé est idéal pour un apéritif, un déjeuner en plein air ou un moment de détente au soleil sur les transats fournis.","t9ff4c942e2":"<span class=\"room-stat-val\">2</span> <span class=\"room-stat-lbl\">Personnes max</span>","ta0fa0d69d8":"Sur la route Gargnano–Riva del Garda. Parking privé gratuit réservé aux clients.","ta13fa83e74":"Directement au bord de l'eau, le Prà est entouré de nature. Derrière s'élève une paroi rocheuse avec une cascade enchanteresse ; devant, la vue s'ouvre sur le lac bleu et le Monte Baldo. La famille Parisini gère elle-même la propriété depuis des siècles.","ta1dd17aff1":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Cuisine équipée</span>","ta23177374a":"Comment vient-on en voiture ?","ta3eb0373a9":"Autoroute A4, sortie Desenzano, direction Salò : environ 15 km. De Salò, continuer vers Riva del Garda par la Gardesana, la SS 45 bis ; après Gargnano, encore 4 km jusqu’à Porto di Tignale.","ta4e82da719":"Pierre apparente, escalier en porte-à-faux et jardin réservé","ta505f0bda2":"Devant, le lac ouvert et le Monte Baldo sur la rive véronaise : par temps clair, la vue va de Malcesine jusqu'à Sirmione. Derrière, à quelques mètres, s'élève une paroi rocheuse avec une cascade.","ta513f6fd85":"<span class=\"svc-ico\">🏡</span><span class=\"svc-label\">Terrasse privée</span>","ta5d6510b68":"Chambre double communicante avec une chambre à lits superposés — idéale pour les familles avec enfants.","ta6c3703937":"<span class=\"svc-ico\">🐾</span><span class=\"svc-label\">Animaux acceptés</span>","ta86d900f98":"Familiale","ta8ab81a313":"<span class=\"rv-name\">🇺🇸 Hua</span><span class=\"rv-date\">Juillet 2025 · Chambre Double Economy</span>","ta99d92066e":"L'appartement Bergamotto se développe sur deux niveaux. Au rez-de-chaussée, une chambre double et une grande salle de bain avec douche. Sous les combles, le séjour avec coin cuisine et la possibilité d'ajouter un troisième couchage. Les intérieurs en pierre apparente et l'escalier en porte-à-faux qui relie les deux niveaux donnent à l'ensemble une atmosphère intime et fraîche.","ta9faca02a1":"Du plus proche au plus lointain : Brescia Montichiari, Verona Villafranca, Bergamo Orio al Serio, Milan Linate, Venise et Milan Malpensa.","taa63f05b34":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Vue lac</span>","taab30c2acb":"Oui, les chiens sont les bienvenus, aussi bien en chambre qu'en appartement. Le supplément est de 10 € par nuit et par animal à l'hôtel et de 50 € par séjour et par animal dans les appartements — non pas par nuit : pour tout le séjour.","tab8585e7c5":"Accepter","tabbd679e0c":"En pratique : la chambre pour un court séjour sans souci, l'appartement pour une semaine, pour les familles avec enfants ou pour qui veut faire ses courses et cuisiner.","tabc17b94c9":"La Limonaia · Écomusée","tabe7c8dd16":"<span class=\"svc-ico\">📶</span><span class=\"svc-label\">Wi-Fi gratuit</span>","tac18715e60":"Canyoning et escalade sur la paroi rocheuse à la cascade derrière le Prà. Pour les plus téméraires.","tae509f55e2":"Dans la limonaia historique","taebe065059":"Ils s'achètent à l'hôtel pendant le séjour ; la vitrine avec tous les produits se trouve sur pradelafam.shop.","tafb272106a":"Appartements","tb07c72fa37":"⚠️ Appartement temporairement indisponible","tb3672026f9":"Rez-de-chaussée · Entrée privée","tb3879c037a":"Le vent caractéristique du lieu permet aux amateurs de surf, de kitesurf et de voile de s'amuser toute la journée.","tb3e178fcce":"Que voit-on depuis l'établissement ?","tb498c356db":"<span>Tignale</span><span class=\"dot\">·</span><span>Lac de Garde</span><span class=\"dot\">·</span><span>Hôtel & Appartements</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Écomusée de la Limonaia</span><span class=\"dot\">·</span><span>Planche à voile & Kitesurf</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>La famille Parisini</span><span class=\"dot\">·</span> <span>Tignale</span><span class=\"dot\">·</span><span>Lac de Garde</span><span class=\"dot\">·</span><span>Hôtel & Appartements</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Écomusée de la Limonaia</span><span class=\"dot\">·</span><span>Planche à voile & Kitesurf</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>La famille Parisini</span><span class=\"dot\">·</span>","tb4aad9f0d8":"Découvrir","tb6c4ca4ea6":"Grandes baies vitrées sur le lac, cuisine équipée, jardin avec terrasse privée. Mobilier en bois.","tb6f6d38b2a":"Le Plan","tb7043e80ae":"La plus grande et la plus septentrionale des limonaie d'Europe. Visitable de Pâques à octobre.","tb83f0fe0df":"Peut-on se baigner ? Comment est la plage ?","tb920ed0f41":"Le studio Kumquat dispose d'un lit double, d'un coin cuisine pratique et d'une grande salle de bain avec douche. De l'intérieur comme du jardin privé — idéal pour un apéritif, un déjeuner en plein air ou un moment de détente sur les transats fournis — on profite d'une vue magnifique sur le lac, de Malcesine jusqu'à Sirmione.","tba8e493ffa":"Au téléphone, c'est la famille qui gère l'établissement qui répond. Appelez ou écrivez : nous vous dirons ce qu'il en est vraiment, même quand la réponse est « cette semaine-là, nous sommes complets ».","tba9319bd60":"05 — Où nous sommes","tba9601ab9f":"03 — Chambres, appartements et services","tbb5791de12":"Fabuleux","tbe9b82ffd6":"Sans colorants ni conservateurs, ancienne distillerie locale","tbeaaa45bce":"Randonnée & VTT","tbf926697bb":"Pour ceux qui dorment en chambre, oui, et il est compris dans le prix : il est servi sous la véranda, à l'ombre des oliviers, avec vue sur le lac.","tbf9a913713":"Autoroute A4, sortie Brescia Est, direction Salò : environ 20 km. Ensuite comme ci-dessus.","tbfadec1a86":"Au piment ou au poivre. Pour salades, poisson ou viandes crues","tc00c837bbd":"<span class=\"svc-ico\">♨️</span><span class=\"svc-label\">Micro-ondes</span>","tc058c4cdc9":"Le studio Calamondino offre une splendide vue sur le lac grâce à ses grandes baies vitrées. Il dispose d'un lit double, d'un coin cuisine et d'une salle de bain avec douche. Le mobilier en bois, les finitions soignées et l'équipement fonctionnel le rendent particulièrement confortable, surtout en demi-saison. À l'extérieur, un grand jardin privé est parfait pour un apéritif, un déjeuner en plein air ou une pause au soleil sur les transats fournis.","tc16b56a0bd":"Pour les journées tranquilles : Gargnano à quelques kilomètres, Limone sul Garda et Riva del Garda vers le nord, le sanctuaire de Montecastello au-dessus de Tignale.","tc3244756f3":"Tignale fait partie du parc Alto Garda Bresciano et, au-delà des sentiers du parc, conserve un réseau très dense de sentiers militaires — désormais oubliés des cartes — reliant tranchées, abris, postes en galerie et casemates. Presque toujours aux endroits les plus panoramiques.","tc3be219c28":"<span class=\"bcs-val\">2 pers.</span><span class=\"bcs-lbl\">Capacité</span>","tc4e9ccf33d":"Rechercher →","tc4f2d54efd":"Salle de bain privée avec douche, sèche-cheveux, jeu de serviettes, gel douche et kit de courtoisie ; climatisation, Wi-Fi gratuit, télévision et un réfrigérateur vide à disposition.","tc51398d85e":"<span class=\"room-stat-val\">23m²</span> <span class=\"room-stat-lbl\">Surface</span>","tc5f475fec9":"<span class=\"bcs-val\">3 pers.</span><span class=\"bcs-lbl\">Capacité</span>","tc5fad9b6ee":"<span class=\"room-stat-val\">65m²</span> <span class=\"room-stat-lbl\">Surface</span>","tc63a6303e9":"Ce n'est pas une limonaia reconstituée pour la visite : elle est vivante et en production, et ses fruits deviennent les citrons au sel, le limoncino et le sirop que l'on déguste à la fin du parcours.","tc6ae6580d2":"Personnes","tc76eb4a334":"Premier et deuxième étage","tcb93134e47":"C'est comme rentrer à la maison. Le lieu est enchanteur, en pleine nature, et le lac est splendide.","tcc609e0585":"<span class=\"svc-ico\">🌳</span><span class=\"svc-label\">Jardin privé</span>","tcd38f168ec":"Prà de la Fam® est une marque déposée en Italie par FAM S.r.l.","tce08c37a2c":"Les expériences réelles de ceux qui ont séjourné au Prà de la Fam.","tceef27f1f7":"Qu'est-ce que la Limonaia del Prà de la Fam ? Peut-on la visiter ?","tcf268eb913":"Avis","tcf4012d7d5":"À l'hôtel → Découvrir","td075d0c609":"Golf de Bogliaco","td0bf44ac3a":"La région","td0bffd1f6d":"Mugs & Accessoires","td0c5b92b23":"Les appartements portent le nom d’un agrume de la limonaia. La clémentine est l’hybride d’une orange et d’une mandarine.","td0e7331b28":"Planche à voile & Kitesurf","td122cacdeb":"L'ancienne demeure du jardinier. Entrée privée, vue lac, coin cuisine. À quelques pas de la plage.","td1523d1952":"Double Standard","td2f58fcd68":"<span class=\"bcs-val\">16 m²</span><span class=\"bcs-lbl\">Surface</span>","td4b6fcbd5b":"Depuis l’est","td5068d47a5":"Comment réserver ? Vaut-il mieux réserver sur le site ?","td62becd9e0":"Saisissez « Prà de la Fam » ou « Porto di Tignale ». N'indiquez pas seulement « Tignale » : le GPS vous emmène au village, en haut de la montagne, et il faut ensuite redescendre.","td96b889af3":"Suivez-nous","td97b396efc":"Le confort essentiel, un emplacement imbattable","tdac219b4c6":"La randonnée et le VTT partent directement d'ici : nous sommes dans le Parc Alto Garda Bresciano et, au-delà des sentiers du parc, il existe un réseau très dense de chemins militaires — tranchées, abris, galeries et casemates — disparus des cartes, presque toujours aux points les plus panoramiques.","tdd0355ae67":"Chambres doubles lumineuses avec vue sur le lac de Garde et les montagnes environnantes.","tdd63715330":"La visite est guidée et raconte comment fonctionnaient les limonaie du lac de Garde : les piliers de pierre, les planches qui fermaient la serre l'hiver, le commerce des citrons vers l'Europe du Nord. À la fin, une dégustation des produits nés ici : citrons au sel, limoncino, sirop de citron et huile aux agrumes. Horaires et informations sur le site dédié, ecomuseopradelafam.com.","tde4616b554":"Cela dépend de la durée du séjour et de l'envie de cuisiner. Les chambres sont au nombre de dix : Double Standard (18 m²), Double Economy (16 m²), Triple (23 m²) et Familiale (29 m²), toutes avec salle de bain privée, climatisation, Wi-Fi et petit-déjeuner inclus servi sous la véranda. C'est le choix le plus simple pour deux ou trois nuits.","tdedb012719":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Wi-Fi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Familles</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Salle de bain privée</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Petit-déjeuner</span>","tdef993fa85":"<span class=\"svc-ico\">🚗</span><span class=\"svc-label\">Parking gratuit</span>","tdf027beffb":"Citron et oranges amères. Latteria Turnaria di Tignale","tdf45fca4d2":"<span class=\"rv-name\">🇵🇱 Grzegorz</span><span class=\"rv-date\">2025 · Pologne</span>","tdf7cb322cf":"Studio avec grandes baies vitrées sur la limonaia, cuisine équipée et terrasse privée.","te212539cb8":"Réserver une chambre →","te2cfa28881":"<span class=\"room-stat-val\">18m²</span> <span class=\"room-stat-lbl\">Surface</span>","te3f65a8ce9":"La Limonaia du Prà de la Fam a été restaurée en 1985 avec le concours de la Comunità Montana du Parc Alto Garda Bresciano. Ses 80 arbres adultes composent aujourd'hui l'Écomusée, visitable de Pâques à octobre.","te570deba88":"04 — Sport & Nature","te594ea220c":"Où","te5cc02c791":"<span class=\"room-stat-val\">3</span> <span class=\"room-stat-lbl\">Personnes max</span>","te5de2cbb0d":"Prà de la Fam · Appartement","te6b441803d":"<span class=\"svc-ico\">📺</span><span class=\"svc-label\">Télévision</span>","te6e178ccc8":"Politique de cookies","te8106f1430":"Emplacement fantastique, une petite perle sur le lac de Garde. Matteo, propriétaire et gérant, est extrêmement gentil et nous a raconté et conseillé énormément de choses. Emplacement exclusif, endroit magnifique et charmant — j'y reviendrais mille fois. Parking privé et fermé (parfait pour les motards comme moi) et fenêtres neuves : aucun bruit dans la chambre.","te8c99f06b1":"Hôtel et Appartements directement sur le lac de Garde, à l'intérieur de la limonaia historique la plus septentrionale d'Europe. Une cascade de roche derrière, le lac bleu devant — là où le temps s'arrête.","teb07e74228":"02 — L'emplacement et la limonaia","tec5181be2c":"Voici les questions que l'on nous pose vraiment au téléphone et à la réception, avec la réponse complète — la même que nous donnerions de vive voix. Si ce que vous cherchez n'y est pas, appelez-nous : c'est nous qui répondons, pas un standard.","tecb5de2726":"Les départs se font à pied depuis l'hôtel : sentiers du Parc Alto Garda et anciens chemins militaires panoramiques.","ted709911db":"Lumineuse, moderne, vue lac ou montagne","tede794f1e2":"03 — Écomusée","tef84d416a9":"En train","tefcd26e01b":"Où<br><em>nous sommes</em>","tf03b6bab86":"Pas pour les appartements, puisqu'ils disposent d'une cuisine : ceux qui le souhaitent peuvent l'ajouter en supplément. Il suffit de le dire à la réservation, ou même la veille à la réception.","tf08ba2a641":"Notre<br><em>propriété</em>","tf11b96d58c":"Les chambres ont vue sur le lac ou sur la montagne selon leur position dans le bâtiment ; les appartements donnent tous sur le lac. Le petit-déjeuner est servi sous la véranda, à l'ombre des oliviers, face au lac.","tf1c8b4462a":"En voiture","tf2137a9a21":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Réfrigérateur</span>","tf27cd0f01e":"<span class=\"svc-ico\">💨</span><span class=\"svc-label\">Sèche-cheveux</span>","tf297f278b2":"Situé à Tignale, village typique du lac de Garde sur la route de Riva, à quelques kilomètres de Gargnano, le Prà de la Fam jouit d'un emplacement idéal pour des vacances tranquilles ou sportives.","tf3822d6248":"Comment est la route ? J'ai lu qu'elle était étroite et pleine de tunnels.","tf38421c0d2":"Via Gardesana, 7 · Sponda bresciana<br>Route Gargnano–Riva del Garda","tf4467cd18b":"Questions","tf561d3c688":"L'ancienne demeure du jardinier, renée","tf5795ea6fe":"Vue de Malcesine à Sirmione, jardin privé avec transats. Coin cuisine, salle de bain avec douche.","tf757da1422":"La nature","tf946f40316":"Chambres","tfc36cf0b38":"Planche à voile, kitesurf et voile : le vent du lac de Garde est constant et régulier, et le Circolo Vela Gargnano organise des régates toute la saison, dont l'historique Centomiglia.","tfde24d0272":"Deux-pièces sur deux niveaux, pierre apparente, escalier en porte-à-faux et jardin réservé. Le plus spacieux de la propriété.","tfe69b1ca69":"Deux chambres communicantes pour toute la famille","tfe6bf92cf4":"La propriété appartient toujours à la famille Parisini. Les visites guidées racontent l'histoire et les particularités de la limonaia et se terminent par une dégustation des produits : citrons au sel, limoncino, sirop de citron et huile aux agrumes.","tff12d938aa":"Réserver en ligne","tff9b24f4c2":"Les appartements sont aménagés dans l'ancienne limonaia : Clementina, Calamondino, Kumquat et Pomelo font environ 35 m² pour deux personnes, avec cuisine équipée ou coin cuisine, espace extérieur et vue sur le lac ; Bergamotto se développe sur deux niveaux, 65 m², mais n'est pas disponible actuellement.","tffdf35b0f8":"Les chiens sont-ils acceptés ?"},"es":{"t002b752f7c":"Tres camas, baño privado, ideal para grupos de amigos o familias con un niño. Acceso directo al jardín y a la playa.","t00d3f340d3":"Encaramado sobre el lago de Garda, Tignale es un destino reconocido del turismo internacional.","t00dda435d9":"Reservar ahora →","t0157951bb7":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Vista a la montaña</span>","t0268fb0ea8":"¿No ha encontrado la respuesta?","t02b83bc7a6":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Vista al jardín</span>","t04268fbc76":"Escalada","t044ccabb57":"<span class=\"svc-ico\">🚿</span><span class=\"svc-label\">Ducha</span>","t049011f98d":"Los apartamentos llevan el nombre de un cítrico de la limonaia. El calamondín es una mandarina pequeña, muy jugosa y dulce.","t0794554adf":"Grandes ventanales, luz del lago, jardín","t085726e29d":"Tignale · Via Gardesana, 7 · Porto di Tignale · Lago de Garda","t092ab3f505":"Una vez aquí se está muy bien incluso sin coche: playa, limonar y senderos salen de la puerta. Para recorrer los demás pueblos del lago, en cambio, ayudan el coche o el barco.","t09ef86ca9b":"Servicios incluidos","t0a015b54e8":"Salida","t0a1b390212":"Galería de fotos","t0aae14be2b":"Llegando desde el norte: estación de Rovereto, autobús hasta Riva del Garda y desde allí la línea hacia Gargnano.","t0ce18bb3ab":"Visita ecomuseopradelafam.com →","t0ec5e15397":"<span class=\"svc-ico\">🥐</span><span class=\"svc-label\">Desayuno incluido</span>","t0f15cc4caa":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Cocina americana</span>","t0f9627b57b":"<span class=\"rv-name\">🇮🇹 Tommaso</span><span class=\"rv-date\">Agosto 2024 · Habitación Doble</span>","t0ffeeaad93":"desde la recepción.","t116994d1f1":"Sí. Las estaciones cómodas son Brescia y Desenzano–Sirmione, en la línea Milán–Venecia; desde allí salen los autobuses que recorren la Gardesana, más frecuentes desde Brescia y más escasos desde Desenzano. Se baja en la parada «Porto di Tignale», que está delante de nosotros.","t119436bb10":"<span class=\"svc-ico\">🌿</span><span class=\"svc-label\">Espacio exterior</span>","t12e5204303":"¿El desayuno está incluido?","t134b097f44":"¿Mejor una habitación de hotel o un apartamento?","t1475215d61":"Lo que se ve desde aquí y qué es ese limonar.","t163ba9bcc4":"Habitaciones dobles amplias y confortables, en la primera o segunda planta del hotel. Algunas ofrecen vista exclusiva al lago de Garda, otras combinan una espléndida vista al lago y a las montañas circundantes, según su posición en el edificio. El mobiliario es moderno y acogedor. Incluye: aire acondicionado, Wi-Fi gratuito, TV, nevera vacía y aparcamiento reservado gratuito. Los baños cuentan con ducha, secador, juego de toallas, gel y kit de aseo.","t1672e78ca1":"Ver disponibilidad →","t16ef7fdba4":"Madera, piedra y silencio en la histórica limonaia","t16f921ca52":"Dónde estamos","t177195854b":"Vista de Malcesine a Sirmione, jardín privado","t189b807e55":"Las habitaciones dobles economy, en la primera y segunda planta del hotel, son algo más compactas pero igual de confortables. Todas ofrecen vista al lago de Garda y están amuebladas con un estilo moderno y acogedor. Cuentan con aire acondicionado, TV, Wi-Fi gratuito y nevera vacía. El baño, recientemente reformado, dispone de ducha, secador, juego de toallas, gel y kit de aseo. Aparcamiento reservado gratuito incluido.","t1a4e01727f":"Prensado en frío. También disponible con cítricos","t1acc2b334c":"No tenemos piscina, y nunca la hemos echado de menos: aquí se nada en el lago.","t1afd65f4cd":"Contacto","t1d07da6684":"Apt. Clementina","t1e5e550e0d":"En el lago de Garda hay muchos limonares históricos, pero casi todos son estructuras vacías: quedan los pilares y los muros, no las plantas. El nuestro sigue cultivado y es el más grande y el más septentrional de Europa: crece justo en el límite climático más allá del cual un limonero ya no aguanta al aire libre.","t1e65935b2b":"Italiano, inglés, alemán, francés y español, tanto en recepción como en todo el sitio web. La familia gestiona el alojamiento en persona: quien contesta al teléfono es quien le recibirá a su llegada.","t1f0dbd96ab":"Habitaciones","t1f3d2afb49":"Habitación doble con baño privado, vista al lago o al jardín. Mobiliario cuidado, ventanas nuevas sin ruido. Desayuno incluido en la veranda.","t207ef0e5ad":"¿Qué debo poner en el navegador?","t21a221f032":"<span class=\"svc-ico\">✨</span><span class=\"svc-label\">Limpieza final</span>","t21e4cfe334":"Habitación · Prà de la Fam","t226b000df2":"Explora la propiedad: hotel, apartamentos, limonaia, senderos y aparcamiento. Pasa por encima de los puntos para ver los detalles.","t23d419716f":"Reservando directamente habla con nosotros y no con un intermediario: las peticiones especiales — el perro, el desayuno en el apartamento, la llegada tarde, una habitación cerca del jardín — se resuelven en dos líneas de correo.","t251c5c5589":"Alojamientos","t25fcc2c679":"¿Se puede llegar sin coche, en tren o en avión?","t2768309b26":"¿Qué idiomas hablan?","t277537d39c":"Aceite de oliva virgen extra ecológico","t2779f6af30":"Para quien se aloja aquí la diferencia práctica es sencilla: el limonar no es una excursión que haya que programar, es el jardín junto a la habitación. Y los cinco apartamentos están hechos dentro del antiguo limonar, tanto que llevan el nombre de un cítrico: Clementina, Calamondino, Kumquat, Pomelo, Bergamotto.","t27c22ff3e6":"Cookies y privacidad","t282d4f9757":"Habitación Doble","t29439a78d2":"¿Listo para<br><em>reservar?</em>","t294fe37686":"Hotel — 10 habitaciones","t2a3ace25d3":"01 — La carretera y la llegada","t2adafad680":"Estamos a tu disposición para cualquier información.","t2b2d8e27c6":"Aceite de oliva virgen extra ecológico, ropa y accesorios con el logo del Prà de la Fam. Disponibles en el hotel durante la estancia.","t2c4531f1c4":"Aceite de oliva virgen extra del Garda","t303332408e":"<span class=\"svc-ico\">🚪</span><span class=\"svc-label\">Baño privado</span>","t303af58209":"Desde el oeste","t30de35ddfd":"Prà de la Fam · Información","t310e4bca25":"Las habitaciones triples, en la primera y segunda planta del hotel, han sido renovadas recientemente y ofrecen una espléndida vista al lago de Garda. Amuebladas con estilo moderno, disponen de todas las comodidades gratuitas: televisor, aire acondicionado, nevera vacía y Wi-Fi. Los baños, completamente nuevos, son espaciosos y cuentan con ducha, secador y kit de aseo.","t3182984c6c":"La entrada es de 14:00 a 20:00 y la salida antes de las 10:30.","t321480eea5":"⚠️ El apartamento se encuentra en la histórica limonaia y se accede por numerosos escalones: no es adecuado para personas con movilidad reducida.","t33651bcbf3":"¿En qué se diferencia su limonar de los otros del lago de Garda?","t33c92d054c":"Con el botón «Reservar» del sitio se abre nuestro motor de reservas, con disponibilidad en tiempo real y confirmación inmediata. También puede llamar al (+39) 0365 799890 o escribir a info@alpradelafam.com.","t342c9c14f0":"Los senderos olvidados","t34dc9f10fe":"Opiniones<br><em>de nuestros huéspedes</em>","t34e09946bd":"<span class=\"rv-name\">🇵🇱 Tomek</span><span class=\"rv-date\">Junio 2025 · Habitación Doble Economy · 7 noches</span>","t35323ab850":"Es cierto, y es también el motivo por el que vale la pena el viaje. La Gardesana Occidentale está excavada en la roca sobre el lago: estrecha, con muchos túneles, algunos de los cuales se abren al agua. Es una de las carreteras más panorámicas de Italia.","t35e33176d7":"Sí, el aparcamiento es privado, gratuito y reservado a los huéspedes, justo delante del alojamiento. Es cerrado, así que va bien también para las motos: es una de las cosas que más mencionan los moteros en sus reseñas.","t36cd9798d3":"Cocina equipada, mobiliario de madera. Vista al lago y al jardín.","t373f10061d":"Los apartamentos llevan el nombre de un cítrico de la limonaia. La bergamota da el aceite esencial que está en la base del agua de colonia.","t37593677ae":"¿Dónde está exactamente Prà de la Fam?","t376351c53f":"<span class=\"apt-feat\">A/C</span><span class=\"apt-feat\">Cocina</span><span class=\"apt-feat\">WiFi</span><span class=\"apt-feat\">Cama de matrimonio</span>","t37c41cd8c9":"Espacio y confort para tres, frente al lago","t37c595f16c":"Solo necesarias","t380557569e":"Autopista del Brennero A22, salida Rovereto Sud, dirección Riva del Garda, luego la Gardesana hacia Brescia durante unos veinte kilómetros.","t38b0016ada":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Baño privado</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Desayuno</span>","t398dc61e6a":"Teléfono","t3ba43a112b":"Territorio y deporte","t3bb12c5cc5":"Desde el oeste: autopista A4, salida Brescia Est, dirección Salò, unos 20 km, y luego como arriba.","t3c7ffbd79b":"Llévate el lago<br><em>contigo.</em>","t3ca4a501a2":"Camisetas y sudaderas","t3e3e2e7ec7":"📞 Llamar: +39 0365 799890","t3e669ed4d0":"Sí. Aceite de oliva virgen extra ecológico de primera presión en frío, aceite de cítricos, limones en sal con guindilla o pimienta, limoncino sin colorantes ni conservantes, sirope de limón y mermeladas ecológicas de limón y naranja amarga, además de ropa y accesorios con el logotipo del Prà.","t3e730c4314":"En la misma propiedad está la Limonaia del Prà de la Fam: el limonar más grande y más septentrional de Europa, con ochenta árboles todavía en producción, visitable de Pascua a octubre. Es lo que aquí no tiene ningún otro hotel del Garda, y los cinco apartamentos están hechos justo allí, en el antiguo limonar.","t3f0a50c945":"Solo le pedimos que lo indique al reservar, así podemos asignarle el alojamiento más cómodo. Alrededor está el jardín, la playa es libre y los senderos del parque salen de la puerta: para un perro es un sitio fácil.","t3f47d99b7d":"Estudio con cama de matrimonio, cocina y jardín privado con vista panorámica al lago.","t3f59fc3c84":"Estudio con cocina equipada, mobiliario de madera y gran jardín privado.","t405e497d1d":"220 opiniones verificadas · Booking.com","t4067735dc5":"<span class=\"room-stat-val\">4</span> <span class=\"room-stat-lbl\">Huéspedes máx.</span>","t409c8e4975":"Dirección","t41bc46e952":"Es el limonar más grande y más septentrional de Europa, y está dentro de nuestra propiedad: desde la habitación se llega a pie en un minuto. No es una ruina ni una reconstrucción: los ochenta árboles adultos están vivos y en producción.","t41c8f32a08":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Nevera vacía a disposición</span>","t4353996ec1":"<span class=\"svc-ico\">☀️</span><span class=\"svc-label\">Terraza</span>","t43a4b78b40":"Descubre los apartamentos","t43d51909d4":"Disponibilidad en tiempo real con nuestro motor de reservas. Confirmación inmediata.","t44013397ef":"Sí. La playa está a menos de veinte metros del jardín: se cruza el césped y ya se está en el agua. Es una playa pequeña y libre, no un balneario: ni filas de sombrillas ni verjas.","t44e1690ba5":"¿Qué hay en la habitación?","t486b047c5e":"Usamos cookies analíticas para entender cómo se usa el sitio y mejorarlo. Ningún dato se cede a terceros con fines publicitarios.","t48a4ee031f":"Se recorre con normalidad en coche, en moto y en autocaravana — los autobuses de línea pasan a diario — siempre que se vaya despacio y sin prisa en los cruces dentro de los túneles. El consejo que damos a todos: calcular media hora más y parar en uno de los apartaderos: desde allí se ve todo el lago.","t49218f6b75":"No hace falta reservarlo ni avisar con antelación: hay sitio para todos los huéspedes.","t49448908e0":"<span class=\"room-stat-val\">🌊</span> <span class=\"room-stat-lbl\">Vista al lago</span>","t4a7cce2b7a":"Un hotel con<br><em>una ubicación ideal.</em>","t4da9c9af96":"Habitación","t507171eb65":"Recientemente renovada, con vista al lago y todo el confort para tres personas.","t51b9fc85e9":"Preguntas frecuentes","t52ec2ad3f5":"En coche, en tren, en avión","t52fef421c2":"Abrir en Google Maps →","t548a496993":"¿Qué se puede hacer en la zona?","t558bacaaaa":"Apartamento · Prà de la Fam","t55de887092":"Tienda","t5624b2aeef":"Nuestros<br><em>apartamentos</em>","t5688e3684d":"El lago aquí es limpio y profundo; la temporada de baño va aproximadamente de junio a septiembre. Por la mañana el agua es un espejo, por la tarde se levanta el viento: por eso el tramo que tenemos delante lo frecuentan quienes hacen windsurf y kitesurf.","t59f7f88684":"<span class=\"svc-ico\">🛎️</span><span class=\"svc-label\">Ropa de cama incluida</span>","t5acc558e2c":"<span class=\"svc-ico\">🚭</span><span class=\"svc-label\">No fumadores</span>","t5be0bd6124":"Todos conectados en tren o autobús con las estaciones de Brescia, Desenzano y Verona, desde donde se sigue por la Gardesana.","t5c40bb1a86":"06 — Lo que dicen de nosotros","t5e16e39fef":"Canyon Adventures — especialistas en barranquismo en el Garda desde hace más de 20 años. Cañones del Garda y Valle di Ledro.","t5ff2e24a05":"Nuestras <em style=\"font-style:italic;color:var(--gold-titolo)\">habitaciones</em>","t606dccfdd7":"Desde el este: autopista A4, salida Desenzano, dirección Salò, unos 15 km. Desde Salò se sigue hacia Riva del Garda por la Gardesana, la SS 45 bis; pasado Gargnano, otros 4 km hasta Porto di Tignale.","t610f5e52ac":"Prà de la Fam, lago de Garda","t6649158d5f":"Planta baja + buhardilla · Entrada desde el sendero Oldesio","t67275fe941":"Desde el norte","t686954d940":"El último tramo antes de llegar es un túnel: la entrada del Prà de la Fam está justo después, a la derecha si viene de Gargnano.","t6887a8d847":"Antigua vivienda del jardinero de las limonaie, Pomelo es hoy un refinado apartamento de unos 35 m² que une el encanto histórico al confort moderno. Cuenta con entrada privada, zona de estar con cocina americana equipada, luminoso dormitorio doble con vista al lago de Garda y baño moderno. A pocos pasos de la playa, Pomelo ofrece una estancia íntima y serena, ideal para quien busca naturaleza, silencio y romanticismo en un entorno auténtico.","t69ca9b15cf":"Lo que se pregunta en recepción antes de reservar.","t6a5f93783c":"<span class=\"rv-name\">🇮🇹 Antonella</span><span class=\"rv-date\">Agosto 2024 · Habitación Familiar · 3 noches</span>","t6b0e874d96":"Una batería de artillería, con sus trincheras y búnkeres de protección, se extiende por todo el Monte Castello, cerca del santuario y en las laderas septentrionales. Las líneas defensivas, cuyos restos siguen bien visibles, continúan a lo largo del Dosso Piemp — junto al Rifugio degli Alpini — hasta el Passo della Puria y los confines del municipio.","t6b6fcba8ff":"Mermeladas bio","t6bafccbf5c":"<span class=\"apt-feat\">Vista al lago</span><span class=\"apt-feat\">Cocina</span><span class=\"apt-feat\">Jardín</span><span class=\"apt-feat\">A/C</span>","t6bedaf9568":"Muy espaciosa, con varias camas, pensada para familias con niños. Baño privado amplio con ducha grande. Vista al jardín y acceso a la playa.","t6d55b5df46":"La antigua limonaia del Prà acoge hoy cinco apartamentos de uno o dos ambientes, amueblados con gusto y elegancia.","t6e341fb57d":"Excepcional.","t6e616acee6":"Triple","t6ea05b015c":"La Gardesana es estrecha y llena de túneles, pero es una de las carreteras más panorámicas de Italia: tómense el tiempo de mirarla.","t6f4a1eab99":"Las estaciones cómodas son Brescia y Desenzano–Sirmione, en la línea Milán–Venecia. Desde Brescia los autobuses por la Gardesana son más frecuentes, desde Desenzano más escasos. Se baja en la parada Porto di Tignale.","t70f8bb9a8a":"Inicio","t71f872c875":"<span class=\"svc-ico\">🧴</span><span class=\"svc-label\">Kit de aseo</span>","t7223c24b87":"Fue restaurada en 1985 con la Comunità Montana del Parque Alto Garda Bresciano y hoy es un Ecomuseo, visitable de Pascua a octubre. Sigue siendo propiedad de la familia Parisini, la misma que gestiona el hotel.","t7494b2bbce":"Apt. Calamondino","t75609dc75e":"Desde el norte: autopista del Brennero A22, salida Rovereto Sud, dirección Riva del Garda, y luego la Gardesana hacia Brescia unos veinte kilómetros. La entrada está en la propia Gardesana, con el aparcamiento delante: no hay ninguna carretera de montaña que hacer al final.","t75b631c58e":"Se llega por las viejas carreteras militares que quedan en altura: con el vehículo se avanza hasta donde las pistas son transitables, y luego se sigue a pie o en bicicleta de montaña por los antiguos senderos de acceso.","t75efd8f58e":"Fundado en 1912, 18 hoyos de gran tradición entre Gargnano y Toscolano Maderno. Tercer club de golf de Italia.","t7629980224":"Ver disponibilidad →","t7730c4bbfd":"Descubre la Bottega →","t7781fce007":"<span class=\"bcs-val\">4 pers.</span><span class=\"bcs-lbl\">Capacidad</span>","t778369e4af":"El Circolo Vela Gargnano organiza regatas cada temporada. La tradicional Centomiglia es el evento de vela más esperado del Garda.","t77d524feeb":"<span class=\"rv-name\">🇮🇹 Francesco</span><span class=\"rv-date\">Mayo 2025 · Habitación Doble Economy</span>","t785a762e36":"¿A qué hora son la entrada y la salida?","t7886c29db5":"<span class=\"svc-ico\">🛏️</span><span class=\"svc-label\">Cama de matrimonio</span>","t79f323fa30":"Solo en el hotel → Descubre","t7bf6f8745f":"Toalla y chanclas","t7d590f39bd":"Apartamento","t7d6fd5e619":"02 — Los apartamentos","t7dc7c098bb":"<span class=\"svc-ico\">🌊</span><span class=\"svc-label\">Vista al lago</span>","t7f8cf18395":"Territorio y<br><em>Actividades</em>","t8086d463dc":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Baño privado</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Desayuno</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">A/C</span>","t82253c0699":"Si llega más tarde de las 20:00, llámenos: el alojamiento es de gestión familiar y nos organizamos, solo hace falta saberlo antes. Y si llega antes de hora, normalmente puede dejar ya el coche en el aparcamiento y usar el jardín y la playa mientras terminamos de preparar la habitación.","t8260aa1fca":"El desayuno se sirve en la veranda, a la sombra de los olivos, y el gran jardín es el lugar ideal para estar al sol. La playa está a menos de veinte metros.","t838f87a25f":"Una cascada de roca detrás, el lago y el Monte Baldo delante. Una limonaia en activo a dos pasos.","t839b196b5c":"Apt. Pomelo","t84add5b295":"Correo","t84e7696a19":"Entrada","t85057929c4":"En avión","t85d43acc19":"08 — Ven a visitarnos","t86061d940c":"Directamente sobre el lago. Una cascada de roca detrás, el lago azul y el Monte Baldo delante.","t860cb7ff5c":"Los aeropuertos, del más cercano al más lejano: Brescia Montichiari, Verona Villafranca, Bérgamo Orio al Serio, Milán Linate, Venecia y Milán Malpensa, todos conectados en tren o autobús con Brescia, Desenzano y Verona.","t861e60c1c5":"En dos niveles: dormitorio doble y baño en la planta baja, zona de estar con cocina en la buhardilla. Interiores en piedra vista con característica escalera voladiza.","t865919f6fc":"La opción ideal para disfrutar del lago de Garda con la mejor relación calidad-precio. Baño privado, confort esencial, ubicación inmejorable.","t87da551950":"Bienvenidos<br><em>Al Prà</em><br>de la Fam.","t888a00e0c1":"Cómo llegar","t888f0dc89c":"Reservar ahora","t8920e8076f":"Los apartamentos llevan el nombre de un cítrico de la limonaia. El pomelo es una de las tres especies de las que derivan todos los cítricos: a diferencia de los demás no es esférico, y a menudo tiene forma de pera.","t8943b36bd7":"¿Hay aparcamiento? ¿Se paga?","t89992fa817":"¿Se pueden comprar sus productos?","t89d8242e92":"Situada en la primera o segunda planta del hotel, la habitación familiar se compone de una habitación doble comunicada con otra con literas, ideal para familias con niños. Los espacios han sido reformados recientemente con mobiliario moderno y acogedor. La habitación doble ofrece una sugerente vista al lago, mientras que la segunda da a la ladera de la montaña, garantizando tranquilidad e intimidad. El baño es amplio, con ducha grande, secador y línea de cortesía. La habitación cuenta con todas las comodidades: aire acondicionado, TV de pantalla plana, nevera vacía, Wi-Fi gratuito y kit de bienvenida. Incluye acceso al aparcamiento privado del hotel.","t8a9cf1c412":"Habitación Doble Economy","t8bc3f4c3b5":"Habitación Familiar","t8c79b16206":"Todas las ventanas se han renovado: desde la Gardesana, que pasa justo delante, no entra ruido en la habitación — es una de las cosas que los huéspedes mencionan más a menudo. El alojamiento es para no fumadores.","t8e20ae8c0a":"<span class=\"apt-feat\">Vista al lago</span><span class=\"apt-feat\">Entrada privada</span><span class=\"apt-feat\">Cocina americana</span><span class=\"apt-feat\">A/C</span>","t908bad1849":"Reservar →","t90eab9b683":"Hay algo que confunde a casi todos y conviene saberlo antes de salir: el pueblo de Tignale está arriba, en la montaña, a unos kilómetros de curvas desde la orilla. Nosotros estamos abajo, junto al lago, en la Gardesana. Las coordenadas exactas son 45°43.684′N · 10°43.176′E.","t91922be9e2":"Limones en sal","t919de81cb1":"Además, barranquismo en las gargantas del Garda y del Valle de Ledro, escalada en la pared que hay detrás del hotel y el Golf Bogliaco, fundado en 1912, tercer club de golf de Italia, entre Gargnano y Toscolano Maderno.","t92138ee587":"Habitación Triple","t93167e8876":"01 — Nuestra historia","t9324d6f296":"Prà de la Fam —<br><em>Lago de Garda</em>","t9363a07ad5":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">3 camas</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Baño privado</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Desayuno</span>","t937faf91fe":"Estamos en Via Gardesana 7, Porto di Tignale, 25080 Tignale (BS): orilla bresciana del lago de Garda, en la carretera que une Gargnano con Riva del Garda. El alojamiento está directamente sobre el lago: la playa queda a menos de veinte metros del jardín.","t961e629f7e":"Doble Economy","t965334bacd":"Los apartamentos llevan el nombre de un cítrico de la limonaia. El kumquat, o mandarino chino, da frutos dulcísimos del tamaño de una naranja en miniatura.","t96945f98b8":"La opción ideal para vivir el lago de Garda con la mejor relación calidad-precio.","t96a929601b":"Hotel y apartamentos en el lago de Garda.<br>Via Gardesana, 7 · Porto di Tignale · 25080 Tignale (BS)","t977804b6aa":"Excelente ubicación para visitar toda esta orilla del lago. Vista magnífica con acceso a una pequeña playa, habitación limpia y personal muy amable.","t98513048a0":"Si prefiere ir sobre seguro, introduzca directamente las coordenadas 45°43.684′N · 10°43.176′E, o abra nuestra ubicación en Google Maps desde la página de contactos.","t9885da33e4":"Antigua vivienda del jardinero de las limonaie, hoy un refinado apartamento con vista al lago y entrada privada.","t98b53b16cb":"Dónde estamos de verdad y cómo llegar sin sorpresas.","t9d024253d4":"<span class=\"svc-ico\">❄️</span><span class=\"svc-label\">Aire acondicionado</span>","t9f0d7907bd":"Prà de la Fam · Habitación","t9f408ceb75":"El estudio Clementina dispone de cama de matrimonio, una práctica cocina equipada y un amplio baño con ducha. El mobiliario de madera, los acabados elegantes y el equipamiento funcional lo hacen especialmente acogedor, incluso en las medias estaciones. Desde las ventanas se ven el lago y las montañas de alrededor. El gran jardín privado es ideal para un aperitivo, comer al aire libre o relajarse al sol en las tumbonas.","t9ff4c942e2":"<span class=\"room-stat-val\">2</span> <span class=\"room-stat-lbl\">Huéspedes máx.</span>","ta0fa0d69d8":"En la carretera Gargnano–Riva del Garda. Aparcamiento privado gratuito reservado a los huéspedes.","ta13fa83e74":"Directamente sobre el agua, el Prà está rodeado de naturaleza. Detrás se alza una pared de roca con una cascada encantadora y delante la vista se abre sobre el lago azul y el Monte Baldo. La familia Parisini gestiona directamente la propiedad desde hace siglos.","ta1dd17aff1":"<span class=\"svc-ico\">🍳</span><span class=\"svc-label\">Cocina equipada</span>","ta23177374a":"¿Cómo se llega en coche?","ta3eb0373a9":"Autopista A4, salida Desenzano, dirección Salò: unos 15 km. Desde Salò se sigue hacia Riva del Garda por la Gardesana, la SS 45 bis; pasado Gargnano, otros 4 km hasta Porto di Tignale.","ta4e82da719":"Piedra vista, escalera voladiza y jardín reservado","ta505f0bda2":"Delante, el lago abierto y el Monte Baldo en la orilla veronesa: en los días claros la vista llega de Malcesine hasta Sirmione. Detrás, a pocos metros, se levanta un muro de roca con una cascada.","ta513f6fd85":"<span class=\"svc-ico\">🏡</span><span class=\"svc-label\">Terraza privada</span>","ta5d6510b68":"Habitación doble comunicada con una habitación con literas — ideal para familias con niños.","ta6c3703937":"<span class=\"svc-ico\">🐾</span><span class=\"svc-label\">Se admiten mascotas</span>","ta86d900f98":"Familiar","ta8ab81a313":"<span class=\"rv-name\">🇺🇸 Hua</span><span class=\"rv-date\">Julio 2025 · Habitación Doble Economy</span>","ta99d92066e":"El apartamento Bergamotto se desarrolla en dos niveles. En la planta baja hay un dormitorio doble y un amplio baño con ducha. En la buhardilla se encuentran la zona de estar con cocina americana y la posibilidad de añadir una tercera cama. Los interiores en piedra vista y la escalera voladiza que une los dos niveles dan al ambiente una atmósfera íntima y fresca.","ta9faca02a1":"Del más cercano al más lejano: Brescia Montichiari, Verona Villafranca, Bérgamo Orio al Serio, Milán Linate, Venecia y Milán Malpensa.","taa63f05b34":"<span class=\"svc-ico\">⛰️</span><span class=\"svc-label\">Vista al lago</span>","taab30c2acb":"Sí, los perros son bienvenidos, tanto en las habitaciones como en los apartamentos. El suplemento es de 10 € por noche y por animal en el hotel y de 50 € por estancia y por animal en los apartamentos: no por noche, sino por toda la estancia.","tab8585e7c5":"Aceptar","tabbd679e0c":"En resumen: habitación para una estancia corta y sin complicaciones, apartamento para una semana, para quien viaja con niños o quiere hacer la compra y cocinar.","tabe7c8dd16":"<span class=\"svc-ico\">📶</span><span class=\"svc-label\">Wi-Fi gratis</span>","tac18715e60":"Barranquismo y escalada en la pared de roca con la cascada detrás del Prà. Para los más atrevidos.","tae509f55e2":"En la histórica limonaia","taebe065059":"Se compran en el hotel durante la estancia; el escaparate con todos los productos está en pradelafam.shop.","tafb272106a":"Apartamentos","tb07c72fa37":"⚠️ Apartamento no disponible temporalmente","tb31b676916":"Barranquismo","tb3672026f9":"Planta baja · Entrada privada","tb3879c037a":"El viento característico del lugar permite a los aficionados al surf, al kitesurf y a la vela disfrutar todo el día.","tb3e178fcce":"¿Qué se ve desde el alojamiento?","tb498c356db":"<span>Tignale</span><span class=\"dot\">·</span><span>Lago de Garda</span><span class=\"dot\">·</span><span>Hotel y apartamentos</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Ecomuseo de la Limonaia</span><span class=\"dot\">·</span><span>Windsurf y kitesurf</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>La familia Parisini</span><span class=\"dot\">·</span> <span>Tignale</span><span class=\"dot\">·</span><span>Lago de Garda</span><span class=\"dot\">·</span><span>Hotel y apartamentos</span><span class=\"dot\">·</span><span>Riviera dei Limoni</span><span class=\"dot\">·</span><span>Ecomuseo de la Limonaia</span><span class=\"dot\">·</span><span>Windsurf y kitesurf</span><span class=\"dot\">·</span><span>Monte Baldo</span><span class=\"dot\">·</span><span>La familia Parisini</span><span class=\"dot\">·</span>","tb4aad9f0d8":"Descubrir","tb6c4ca4ea6":"Grandes ventanales al lago, cocina equipada, jardín con terraza privada. Mobiliario de madera.","tb6f6d38b2a":"El Mapa","tb7043e80ae":"La limonaia más grande y más septentrional de Europa. Visitable de Pascua a octubre.","tb83f0fe0df":"¿Se puede uno bañar? ¿Cómo es la playa?","tb920ed0f41":"El estudio Kumquat dispone de cama de matrimonio, una práctica cocina americana y un amplio baño con ducha. Desde el interior y desde el jardín privado — ideal para un aperitivo, una comida al aire libre o un momento de relax en las tumbonas — se disfruta de una magnífica vista del lago, desde Malcesine hasta Sirmione.","tba8e493ffa":"El teléfono lo contesta la familia que lleva el alojamiento. Llame o escriba: le diremos cómo es en realidad, incluso cuando la respuesta sea «esa semana estamos llenos».","tba9319bd60":"05 — Dónde estamos","tba9601ab9f":"03 — Habitaciones, apartamentos y servicios","tbb5791de12":"Fabuloso","tbe9b82ffd6":"Sin colorantes ni conservantes, antigua destilería local","tbeaaa45bce":"Senderismo y BTT","tbf926697bb":"Para quien duerme en habitación sí, y está incluido en el precio: se sirve en la veranda, a la sombra de los olivos, con vistas al lago.","tbf9a913713":"Autopista A4, salida Brescia Est, dirección Salò: unos 20 km. Desde allí como arriba.","tbfadec1a86":"Con guindilla o pimienta. Para ensaladas, pescado o carnes crudas","tc00c837bbd":"<span class=\"svc-ico\">♨️</span><span class=\"svc-label\">Microondas</span>","tc058c4cdc9":"El estudio Calamondino ofrece una espléndida vista al lago gracias a sus grandes ventanales. Dispone de cama de matrimonio, cocina americana y baño con ducha. El mobiliario de madera, los acabados cuidados y el equipamiento funcional lo hacen especialmente confortable, sobre todo en las medias estaciones. Fuera, un amplio jardín privado es perfecto para un aperitivo, comer al aire libre o relajarse al sol en las tumbonas.","tc16b56a0bd":"Para los días tranquilos: Gargnano a pocos kilómetros, Limone sul Garda y Riva del Garda hacia el norte, y el santuario de Montecastello sobre Tignale.","tc3244756f3":"Tignale forma parte del parque Alto Garda Bresciano y, además de los senderos del parque, conserva una red densísima de senderos militares — ya olvidados por los mapas — que unen trincheras, refugios y puestos en galería, casamatas. Casi siempre en los puntos más panorámicos.","tc3be219c28":"<span class=\"bcs-val\">2 pers.</span><span class=\"bcs-lbl\">Capacidad</span>","tc4e9ccf33d":"Buscar →","tc4f2d54efd":"Baño privado con ducha, secador, juego de toallas, gel de baño y kit de cortesía; aire acondicionado, Wi-Fi gratuito, televisión y una nevera vacía a disposición.","tc5f475fec9":"<span class=\"bcs-val\">3 pers.</span><span class=\"bcs-lbl\">Capacidad</span>","tc63a6303e9":"No es un limonar reconstruido para la visita: está vivo y en producción, y de sus frutos nacen los limones en sal, el limoncino y el sirope que se prueban al final del recorrido.","tc6ae6580d2":"Huéspedes","tc76eb4a334":"Primera y segunda planta","tcb93134e47":"Es como volver a casa. El lugar es encantador, rodeado de naturaleza, y el lago es espléndido.","tcc609e0585":"<span class=\"svc-ico\">🌳</span><span class=\"svc-label\">Jardín privado</span>","tcd38f168ec":"Prà de la Fam® es una marca registrada en Italia por FAM S.r.l.","tce08c37a2c":"Las experiencias reales de quienes se han alojado en el Prà de la Fam.","tceef27f1f7":"¿Qué es la Limonaia del Prà de la Fam? ¿Se puede visitar?","tcf268eb913":"Opiniones","tcf4012d7d5":"En el hotel → Descubre","td0bf44ac3a":"El territorio","td0bffd1f6d":"Tazas y accesorios","td0c5b92b23":"Los apartamentos llevan el nombre de un cítrico de la limonaia. La clementina es el híbrido de una naranja y una mandarina.","td0e7331b28":"Windsurf y kitesurf","td122cacdeb":"La antigua casa del jardinero. Entrada privada, vista al lago, cocina americana. A pocos pasos de la playa.","td1523d1952":"Doble Estándar","td1f30cb50f":"Apt. Kumquat","td4b6fcbd5b":"Desde el este","td5068d47a5":"¿Cómo se reserva? ¿Conviene reservar desde la web?","td62becd9e0":"Escriba «Prà de la Fam» o «Porto di Tignale». No ponga solo «Tignale»: el navegador le lleva al pueblo, en lo alto de la montaña, y desde allí hay que volver a bajar.","td96b889af3":"Síguenos","td97b396efc":"Confort esencial, ubicación inmejorable","tdac219b4c6":"A pie y en bicicleta de montaña se sale directamente desde aquí: estamos dentro del Parque Alto Garda Bresciano y, además de los senderos del parque, hay una red densísima de caminos militares — trincheras, refugios, galerías y casamatas — desaparecidos de los mapas y casi siempre en los puntos más panorámicos.","tdd0355ae67":"Habitaciones dobles amplias con vista al lago de Garda y a las montañas circundantes.","tdd63715330":"La visita es guiada y cuenta cómo funcionaban los limonares del lago de Garda: los pilares de piedra, las tablas que cerraban el invernadero en invierno, el comercio de limones hacia el norte de Europa. Al final hay una degustación de los productos que nacen aquí: limones en sal, limoncino, sirope de limón y aceite de cítricos. Horarios e información en la web dedicada, ecomuseopradelafam.com.","tde4616b554":"Depende de cuánto se queden y de cuánto quieran cocinar. Las habitaciones son diez: Doble Estándar (18 m²), Doble Economy (16 m²), Triple (23 m²) y Familiar (29 m²), todas con baño privado, aire acondicionado, Wi-Fi y desayuno incluido servido en la veranda. Es la opción más sencilla para dos o tres noches.","tdedb012719":"<span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">WiFi</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Familias</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Baño privado</span><span style=\"font-size:.6rem;letter-spacing:.08em;background:var(--warm);color:var(--steel);padding:.22rem .65rem\">Desayuno</span>","tdef993fa85":"<span class=\"svc-ico\">🚗</span><span class=\"svc-label\">Aparcamiento gratuito</span>","tdf027beffb":"Limón y naranjas amargas. Latteria Turnaria di Tignale","tdf7cb322cf":"Estudio con grandes ventanales a la limonaia, cocina equipada y terraza privada.","te212539cb8":"Reservar habitación →","te292d68d63":"Apt. Bergamotto","te3f65a8ce9":"La Limonaia del Prà de la Fam fue restaurada en 1985 con la intervención de la Comunità Montana del Parque Alto Garda Bresciano. Sus 80 árboles adultos forman hoy el Ecomuseo, visitable de Pascua a octubre.","te570deba88":"04 — Deporte y naturaleza","te594ea220c":"Dónde","te5cc02c791":"<span class=\"room-stat-val\">3</span> <span class=\"room-stat-lbl\">Huéspedes máx.</span>","te5de2cbb0d":"Prà de la Fam · Apartamento","te6b441803d":"<span class=\"svc-ico\">📺</span><span class=\"svc-label\">Televisión</span>","te6e178ccc8":"Política de cookies","te8106f1430":"Ubicación fantástica, una pequeña perla en el lago de Garda. Matteo, propietario y gestor, es amabilísimo y nos contó y recomendó un montón de cosas. Ubicación exclusiva, un sitio precioso y con encanto — volvería mil veces. Aparcamiento privado y cerrado (ideal para quien va en moto como yo) y ventanas nuevas: cero ruido en la habitación.","te8c99f06b1":"Hotel y Apartamentos directamente sobre el lago de Garda, dentro del limonar histórico más septentrional de Europa. Una cascada de roca detrás, el lago azul delante: donde el tiempo se detiene.","teb07e74228":"02 — El entorno y el limonar","tec5181be2c":"Estas son las preguntas que nos hacen de verdad por teléfono y en recepción, con la respuesta completa: la misma que daríamos en persona. Si lo que busca no está, llámenos: contestamos nosotros, no una centralita.","tecb5de2726":"Las rutas salen a pie desde el hotel: senderos del Parque Alto Garda y antiguos caminos militares panorámicos.","ted709911db":"Amplia, moderna, vista al lago o a la montaña","tef84d416a9":"En tren","tefcd26e01b":"Dónde<br><em>estamos</em>","tf03b6bab86":"Para los apartamentos no, porque tienen cocina: quien quiera puede añadirlo pagando. Basta con decirlo al reservar, o incluso el día antes en recepción.","tf08ba2a641":"Nuestra<br><em>propiedad</em>","tf11b96d58c":"Las habitaciones tienen vistas al lago o a la montaña según su posición en el edificio; los apartamentos miran todos al lago. El desayuno se sirve en la veranda, a la sombra de los olivos, con el lago delante.","tf1c8b4462a":"En coche","tf2137a9a21":"<span class=\"svc-ico\">🧊</span><span class=\"svc-label\">Nevera</span>","tf27cd0f01e":"<span class=\"svc-ico\">💨</span><span class=\"svc-label\">Secador de pelo</span>","tf297f278b2":"Situado en Tignale, pueblo característico del lago de Garda, en la carretera hacia Riva y a pocos kilómetros de Gargnano, el Prà de la Fam goza de una ubicación ideal para unas vacaciones tranquilas o deportivas.","tf3822d6248":"¿Cómo es la carretera? He leído que es estrecha y llena de túneles.","tf38421c0d2":"Via Gardesana, 7 · Sponda bresciana<br>Carretera Gargnano–Riva del Garda","tf4467cd18b":"Preguntas","tf561d3c688":"La antigua casa del jardinero, renacida","tf5795ea6fe":"Vista de Malcesine a Sirmione, jardín privado con tumbonas. Cocina americana, baño con ducha.","tf757da1422":"La naturaleza","tf946f40316":"Habitaciones","tfc36cf0b38":"Windsurf, kitesurf y vela: el viento del lago de Garda es constante y regular, y el Circolo Vela Gargnano organiza regatas durante toda la temporada, incluida la histórica Centomiglia.","tfde24d0272":"Apartamento de dos ambientes en dos niveles, piedra vista, escalera voladiza y jardín reservado. El más espacioso de la propiedad.","tfe69b1ca69":"Dos habitaciones comunicadas para toda la familia","tfe6bf92cf4":"La propiedad sigue perteneciendo a la familia Parisini. Las visitas guiadas cuentan la historia y las particularidades de la limonaia y terminan con una degustación de los productos: limones en sal, limoncino, sirope de limón y aceite cítrico.","tff12d938aa":"Reservar online","tff9b24f4c2":"Los apartamentos están dentro del antiguo limonar: Clementina, Calamondino, Kumquat y Pomelo son de unos 35 m² para dos personas, con cocina equipada o rincón de cocina, espacio exterior y vistas al lago; Bergamotto está en dos niveles, 65 m², pero por ahora no está disponible.","tffdf35b0f8":"¿Se pueden llevar perros?"}};

(function () {
  var LINGUE = ['it', 'en', 'de', 'fr', 'es'];
  var originale = null;            // l'italiano com'era al caricamento

  function raccogliOriginale() {
    if (originale) return;
    originale = {};
    document.querySelectorAll('[data-i18n]').forEach(function (el) {
      originale[el.getAttribute('data-i18n')] = el.innerHTML;
    });
  }

  window.setLang = function (l) {
    if (LINGUE.indexOf(l) < 0) l = 'it';
    raccogliOriginale();
    var d = (l === 'it') ? null : (window.PDLF_T[l] || {});
    document.querySelectorAll('[data-i18n]').forEach(function (el) {
      var k = el.getAttribute('data-i18n');
      var t = d ? d[k] : originale[k];
      // senza traduzione si torna all'italiano: mai una casella vuota
      el.innerHTML = (t !== undefined && t !== null) ? t : originale[k];
    });
    document.documentElement.lang = l;
    document.querySelectorAll('.lang-btn, .flb').forEach(function (b) {
      var suo = (b.getAttribute('onclick') || '').match(/setLang\('(\w+)'\)/);
      b.classList.toggle('active', !!suo && suo[1] === l);
    });
    try { localStorage.setItem('pdlf_lang', l); } catch (e) {}
    // il motore di prenotazione riceve la stessa lingua del sito: era
    // fisso su 'it', quindi un tedesco atterrava in italiano proprio nel
    // momento in cui non deve esitare
    document.querySelectorAll('a[href*="secure-reservation"]').forEach(function (a) {
      a.href = a.href.replace(/([?&]lang=)\w+/, '$1' + l);
    });
    try { if (typeof gtag === 'function') gtag('event', 'cambio_lingua', { nuova: l }); } catch (e) {}
  };

  function iniziale() {
    var l = null;
    try { l = localStorage.getItem('pdlf_lang'); } catch (e) {}
    if (!l) {
      var b = (navigator.languages && navigator.languages[0]) || navigator.language || 'it';
      b = b.slice(0, 2).toLowerCase();
      l = LINGUE.indexOf(b) > -1 ? b : 'it';
    }
    raccogliOriginale();
    if (l !== 'it') window.setLang(l);
    else document.documentElement.lang = 'it';
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', iniziale);
  else iniziale();
})();
